const OFFLINE_AUTH_KEY="elnino_offline_auth_v1";
const OFFLINE_AUTH_MAX_AGE_MS=30*24*60*60*1000; // 30 days since the last successful online authentication.
function getDeviceId(){let id=localStorage.getItem(DEVICE_ID_KEY);if(!id){id=(crypto&&crypto.randomUUID)?crypto.randomUUID():("dev-"+Date.now()+"-"+Math.random().toString(36).slice(2,10));localStorage.setItem(DEVICE_ID_KEY,id)}return id}
const DEVICE_ID=getDeviceId();

// Offline authentication never stores the plain-text password. A device-bound PBKDF2 verifier
// is saved only after a successful online login, allowing a previously verified user to sign in
// during an outage/airplane mode while still requiring the real backend for first-time login.
function offlineAuthKey(username){return String(username||"").trim().toLowerCase()}
async function deriveOfflineVerifier(username,password,salt){
  if(!window.crypto?.subtle) throw new Error("Secure offline authentication is not supported on this device.");
  const material=new TextEncoder().encode(offlineAuthKey(username)+"\u0000"+String(password)+"\u0000"+DEVICE_ID);
  const base=await crypto.subtle.importKey("raw",material,{name:"PBKDF2"},false,["deriveBits"]);
  const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:new TextEncoder().encode(String(salt)),iterations:120000,hash:"SHA-256"},base,256);
  return Array.from(new Uint8Array(bits)).map(b=>b.toString(16).padStart(2,"0")).join("");
}
async function cacheOfflineAuth(password,u,sessionToken=""){
  try{
    const salt=(crypto.randomUUID?crypto.randomUUID():Date.now()+"-"+Math.random());
    const verifier=await deriveOfflineVerifier(u.Username,password,salt);
    const safeUser={};
    ["User_ID","Username","Full_Name","Role","Barangay","Contact_Number","Status","Device_ID"].forEach(k=>{if(u[k]!==undefined)safeUser[k]=u[k]});
    localStorage.setItem(OFFLINE_AUTH_KEY,JSON.stringify({username:u.Username,role:String(u.Role||"").toLowerCase(),barangay:u.Barangay||null,user:safeUser,salt,verifier,sessionToken:String(sessionToken||""),verifiedAt:Date.now()}));
  }catch(e){console.warn("Offline auth cache unavailable",e.message)}
}
function readOfflineAuth(){try{const x=JSON.parse(localStorage.getItem(OFFLINE_AUTH_KEY)||"null");return x&&x.username&&x.salt&&x.verifier?x:null}catch(e){return null}}
async function tryOfflineLogin(username,password,requestedRole){
  const cached=readOfflineAuth();
  if(!cached || offlineAuthKey(cached.username)!==offlineAuthKey(username)) return null;
  if(Date.now()-Number(cached.verifiedAt||0)>OFFLINE_AUTH_MAX_AGE_MS) throw new Error("Offline access expired. Connect to the internet and sign in online to renew this device.");
  if(String(cached.role||"").toLowerCase()!==String(requestedRole||"").toLowerCase()) throw new Error("This device was last verified for a different account role.");
  const verifier=await deriveOfflineVerifier(username,password,cached.salt);
  if(verifier!==cached.verifier) throw new Error("Invalid username or password.");
  return cached;
}
