function getHeatLevel(v){
  v=Number(v);
  if(v>=52)return {key:"extreme-danger",label:"Extreme Danger",cls:"heat-extreme-danger",pin:"pin-extreme-danger"};
  if(v>=42)return {key:"danger",label:"Danger",cls:"heat-danger",pin:"pin-danger"};
  if(v>=33)return {key:"extreme",label:"Extreme Caution",cls:"heat-extreme",pin:"pin-extreme"};
  return {key:"caution",label:"Caution",cls:"heat-caution",pin:"pin-caution"};
}
function heatDataFor(barangay){return heatIndexData.find(x=>x.barangay===barangay)||{barangay,value:0}}
function avgHeat(){return heatIndexData.reduce((s,x)=>s+Number(x.value||0),0)/Math.max(heatIndexData.length,1)}
function renderHeatSummary(prefix,list=heatIndexData){
  const values=list.map(x=>Number(x.value)).filter(Number.isFinite);
  const avgEl=document.getElementById(prefix+"AvgHeat"),maxEl=document.getElementById(prefix+"MaxHeat"),highEl=document.getElementById(prefix+"DangerCount"),extEl=document.getElementById(prefix+"ExtremeCount");
  if(!values.length){if(avgEl)avgEl.textContent="\u2014";if(maxEl)maxEl.textContent="\u2014";if(highEl)highEl.textContent="0";if(extEl)extEl.textContent="0";return}
  const avg=values.reduce((a,b)=>a+b,0)/values.length;
  const max=Math.max(...values);
  const high=list.filter(x=>Number(x.value)>=42).length;
  const extreme=list.filter(x=>Number(x.value)>=33&&Number(x.value)<42).length;
  if(avgEl)avgEl.textContent=avg.toFixed(1)+"\u00B0C";if(maxEl)maxEl.textContent=max.toFixed(1)+"\u00B0C";if(highEl)highEl.textContent=high;if(extEl)extEl.textContent=extreme;
}


