function totalCases(list){return list.length}
function uniqueBarangays(list){return new Set(list.map(r=>r.barangay)).size}
function condCounts(list){
 const m={}; CONDITIONS.forEach(c=>m[c]=0); list.forEach(r=>{m[r.condition]=(m[r.condition]||0)+1}); return m
}
function filteredByPeriod(list, value){
 if(value==="all")return list;
 const now = new Date();
 if(value==="today"){
   const k=now.toISOString().slice(0,10);return list.filter(r=>r.date.slice(0,10)===k)
 }
 const days=parseInt(value);const cutoff=new Date(now);cutoff.setDate(now.getDate()-days+1);
 return list.filter(r=>new Date(r.date)>=cutoff);
}
function countsForBarangay(list){
 const m={};BARANGAYS.forEach(b=>m[b]=0);list.forEach(r=>m[r.barangay]=(m[r.barangay]||0)+1);
 return Object.entries(m).sort((a,b)=>b[1]-a[1]);
}
