function renderAdminUsers(){
  if(!document.getElementById("userBody")) return;
  const q=(document.getElementById("userSearch").value||"").toLowerCase().trim();
  const st=document.getElementById("userStatusFilter").value;
  const list=users.filter(u=>[u.name,u.username,u.barangay||"",u.role||"admin",u.contact||""].join(" ").toLowerCase().includes(q))
                  .filter(u=>st==="all"||u.status===st);

  document.getElementById("userBody").innerHTML=list.map(u=>{
    const role=(u.role||"admin").toUpperCase();
    const idArg=JSON.stringify(String(u.id||""));
    const isPrimaryAdmin=String(u.username||"").toLowerCase()==="admin";
    const deleteBtn=isPrimaryAdmin
      ? `<button class="action-btn action-delete" disabled title="Primary admin account is protected.">Delete</button>`
      : `<button class="action-btn action-delete" onclick='deleteUser(${idArg})'>Delete</button>`;
    return `<tr>
      <td><div style="display:flex;align-items:center;gap:8px"><div class="personnel-avatar-wrap">${userInitial(u)}</div><div><strong>${esc(u.name)}</strong><div style="font-size:9px;color:#64748b">${role}</div></div></div></td>
      <td>${esc(u.username)}</td>
      <td><a class="personnel-contact" href="tel:${esc(u.contact||"")}">\u260E ${esc(u.contact||"\u2014")}</a></td>
      <td><strong>${u.role==="bhw"?esc(u.barangay):u.role==="hospital"?esc(hospitalNameById(u.hospitalId)||"Unassigned hospital"):"ALL BARANGAYS"}</strong></td>
      <td><span class="status ${u.status==="Active"?"badge-online":"badge-offline"}">${u.status}</span></td>
      <td>${esc(u.lastSeen||"Never")}</td>
      <td><div class="action-row"><button class="action-btn action-edit" onclick='editUser(${idArg})'>Edit</button>${deleteBtn}</div></td>
    </tr>`;
  }).join("") || `<tr><td colspan="7" class="empty">No users found.</td></tr>`;
}

function renderBhwRegistrationSummary(){
  const totals=bhwRegistrationSummary?.totals;
  const totalEl=document.getElementById("bhwRegTotal"),activeEl=document.getElementById("bhwRegActive"),inactiveEl=document.getElementById("bhwRegInactive");
  if(totalEl)totalEl.textContent=totals?String(totals.totalAccounts):"—";
  if(activeEl)activeEl.textContent=totals?String(totals.activeAccounts):"—";
  if(inactiveEl)inactiveEl.textContent=totals?String(totals.inactiveAccounts):"—";
  const cards=document.getElementById("bhwRegistrationCards");
  if(!cards)return;
  if(!Array.isArray(bhwRegistrationSummary?.barangays)){
    cards.innerHTML='<div class="empty">Registration totals are not loaded. Connect to the live Apps Script backend and refresh.</div>';
    return;
  }
  cards.innerHTML=bhwRegistrationSummary.barangays.map(b=>`<div class="bhw-registration-card"><div class="brgy-name">${esc(b.barangay)}</div><div class="brgy-count">${Number(b.totalAccounts||0)}</div><div class="brgy-caption">BHW accounts created</div><div class="brgy-status"><span class="status badge-online">Active: ${Number(b.activeAccounts||0)}</span><span class="status badge-offline">Inactive: ${Number(b.inactiveAccounts||0)}</span>${Number(b.pendingAccounts||0)?`<span class="status badge-pending">Pending: ${Number(b.pendingAccounts)}</span>`:""}</div></div>`).join("");
  const updated=document.getElementById("bhwRegistrationUpdated");
  if(updated)updated.textContent="Live counts from Google Sheets Users records"+(bhwRegistrationSummary.generatedAt?" • Updated "+new Date(bhwRegistrationSummary.generatedAt).toLocaleString():"");
}
async function refreshBhwRegistrationSummary(showError=false){
  if(session?.role!=="admin")return;
  if(!LIVE_API_URL||!navigator.onLine){
    if(showError)alert("Registration counts require the live Google Apps Script backend.");
    renderBhwRegistrationSummary();return;
  }
  const cards=document.getElementById("bhwRegistrationCards");
  if(cards&&!bhwRegistrationSummary)cards.innerHTML='<div class="empty">Loading live BHW account totals…</div>';
  try{
    const data=await apiPost("bhwRegistrationSummary",{user:session.user});
    if(!Array.isArray(data.barangays)||!data.totals)throw new Error("Registration summary response was incomplete.");
    bhwRegistrationSummary=data;
    renderBhwRegistrationSummary();
  }catch(err){
    console.warn("BHW registration summary refresh failed",err.message);
    if(showError)alert("Could not load BHW registration totals from Google Sheets.\n\n"+err.message);
    if(cards&&!bhwRegistrationSummary)cards.innerHTML='<div class="empty">Could not load live registration totals. Please check the Apps Script deployment and refresh.</div>';
  }
}

function renderBhwOwnRegistrationSummary(){
  const totalEl=document.getElementById("bhwOwnRegistrationTotal"),statusEl=document.getElementById("bhwOwnRegistrationStatus");
  const own=bhwRegistrationSummary?.barangays?.find(x=>String(x.barangay||"").trim()===String(session?.barangay||"").trim());
  if(totalEl)totalEl.textContent=own?String(own.totalAccounts):"—";
  if(statusEl)statusEl.textContent=own?`${own.activeAccounts} active • ${own.inactiveAccounts} inactive • ${own.totalAccounts} total BHW accounts in ${own.barangay}`:"Could not load BHW account count for your assigned barangay.";
}
async function refreshBhwOwnRegistrationSummary(showError=false){
  if(session?.role!=="bhw")return;
  const totalEl=document.getElementById("bhwOwnRegistrationTotal"),statusEl=document.getElementById("bhwOwnRegistrationStatus");
  if(totalEl&&!bhwRegistrationSummary)totalEl.textContent="…";
  if(statusEl)statusEl.textContent="Loading registered BHW accounts for your assigned barangay…";
  if(!LIVE_API_URL||!navigator.onLine){if(statusEl)statusEl.textContent="Connect to the system to load the latest BHW account count.";return;}
  try{
    const data=await apiPost("bhwRegistrationSummary",{user:session.user});
    if(!Array.isArray(data.barangays)||!data.totals)throw new Error("Registration summary response was incomplete.");
    bhwRegistrationSummary=data;renderBhwOwnRegistrationSummary();
  }catch(err){
    console.warn("BHW own registration summary refresh failed",err.message);
    if(statusEl)statusEl.textContent="Could not load the live count. Please refresh when connected.";
    if(showError)alert("Could not load BHW registration count for your barangay.\n\n"+err.message);
  }
}

