function updatePatientAttachmentList(input){
 const files=Array.from(input?.files||[]),field=input?.closest('.patient-attachment-field'),list=field?.querySelector('.patient-attachment-list');
 if(!list)return;
 if(!files.length){list.textContent='No photos selected.';return;}
 if(files.length>10){list.innerHTML='<span style="color:#b91c1c;font-weight:800">Select no more than 10 photos.</span>';return;}
 list.innerHTML=files.map(f=>`<div>${esc(f.name)} <span class="small-note">(${(f.size/1024/1024).toFixed(2)} MB original)</span></div>`).join('')+`<div class="patient-attachment-note">${files.length} photo(s) selected. Upload requires an internet connection.</div>`;
}
function attachmentEventIdFor(form,file){
 let map={};try{map=JSON.parse(form.dataset.attachmentEventIds||'{}')||{}}catch(_){map={}}
 const key=[file.name,file.size,file.lastModified,file.type].join('|');
 if(!map[key])map[key]='att-'+makeReportId();
 form.dataset.attachmentEventIds=JSON.stringify(map);
 return map[key];
}
async function preparePatientAttachment(file){
 const allowed=['image/jpeg','image/png','image/webp'];
 if(!allowed.includes(String(file.type||'').toLowerCase()))throw new Error('Unsupported photo format: '+file.name+'. Please use JPG, PNG, or WebP. iPhone HEIC photos may need to be converted to JPG first.');
 const objectUrl=URL.createObjectURL(file);
 try{
  const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Could not read image '+file.name+'. Please choose a JPG, PNG, or WebP photo.'));image.src=objectUrl;});
  const maxDim=2200,scale=Math.min(1,maxDim/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((img.naturalWidth||img.width)*scale));canvas.height=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));
  const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image compression is not available in this browser.');
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
  let quality=0.88,dataUrl=canvas.toDataURL('image/jpeg',quality);
  while(dataUrl.length>4100000&&quality>0.58){quality-=0.08;dataUrl=canvas.toDataURL('image/jpeg',quality);}
  if(dataUrl.length>4100000)throw new Error(file.name+' remains too large after compression. Please crop or reduce the image size.');
  const stem=String(file.name||'laboratory-photo').replace(/\.[^.]+$/,'').slice(0,70)||'laboratory-photo';
  return {dataUrl:dataUrl,fileName:stem+'.jpg',mimeType:'image/jpeg'};
 }finally{URL.revokeObjectURL(objectUrl);}
}
async function uploadSelectedPatientAttachments(form,reportId,button){
 const input=form?.querySelector('#rAttachments'),files=Array.from(input?.files||[]);
 if(!files.length)return [];
 if(files.length>10)throw new Error('A patient report can include up to 10 photos.');
 if(!LIVE_API_URL||!navigator.onLine)throw new Error('Photos can only be uploaded while online. Reconnect or remove the selected photos; the report form itself does not require photos.');
 const uploaded=[];
 for(let i=0;i<files.length;i++){
  if(button)button.innerHTML=`<span class="inline-loading"><span class="loading-spinner"></span> Uploading photo ${i+1}/${files.length}…</span>`;
  const prepared=await preparePatientAttachment(files[i]);
  const result=await apiPost('uploadPatientAttachment',{user:session.user,reportId:reportId,clientEventId:attachmentEventIdFor(form,files[i]),fileName:prepared.fileName,dataUrl:prepared.dataUrl});
  if(!result||result.ok!==true||!result.attachment)throw new Error('The backend did not confirm upload of '+files[i].name+'.');
  uploaded.push(result.attachment);
 }
 return uploaded;
}
