function notifyNewHospitalReferrals(referrals){
 if(session?.role!=="hospital"||document.visibilityState!=="visible")return;
 let seen={};try{seen=JSON.parse(sessionStorage.getItem(HOSPITAL_SEEN_REFERRALS_KEY)||"{}")}catch(_){seen={}}
 const pending=(referrals||[]).filter(r=>String(r.Referral_Status||"").toLowerCase()==="pending"&&r.Referral_ID&&!seen[String(r.Referral_ID)]);
 (referrals||[]).forEach(r=>{if(r.Referral_ID)seen[String(r.Referral_ID)]=true});
 try{sessionStorage.setItem(HOSPITAL_SEEN_REFERRALS_KEY,JSON.stringify(seen))}catch(_){ }
 if(pending.length){const first=pending[0];alert("New incoming patient referral"+(pending.length>1?"s":"")+" ("+pending.length+").\nHospital: "+(hospitalData?.hospital?.Hospital_Name||"Assigned hospital")+"\nPatient: "+(first.Patient_Name||"Patient")+"\nPlease review Incoming Patient Referrals.");}
}
