async function refreshConditionsLive(showError=false){
 if(!session||!['admin','bhw'].includes(session.role)||!LIVE_API_URL||!navigator.onLine)return;
 try{const data=await apiPost('conditions',{user:session.user});conditionCatalog=Array.isArray(data.conditions)?data.conditions:[];const active=conditionCatalog.filter(c=>c.Active).map(c=>c.Name);CONDITIONS=active;conditionInputs();const pe=document.getElementById('peCondition');if(pe){const val=pe.value;pe.innerHTML=conditionOptionHtml(val);}const ape=document.getElementById('apeCondition');if(ape){const val=ape.value;ape.innerHTML=conditionOptionHtml(val);}const mount=document.getElementById('modalReportMount');if(mount){const select=mount.querySelector('#conditionChoices');if(select)conditionInputsModal(mount);}renderConditionCatalog();populatePatientFilters();renderAll();}
 catch(err){console.warn('Condition catalog load failed',err.message);if(showError)alert('Could not load the shared condition catalog.\n\n'+err.message);}
}
function renderConditionCatalog(){
 const body=document.getElementById('conditionCatalogBody');if(!body)return;
 body.innerHTML=(conditionCatalog||[]).map(c=>`<tr><td><strong>${esc(c.Name)}</strong></td><td><span class="status ${c.Active?'badge-online':'badge-offline'}">${c.Active?'Active':'Inactive'}</span></td><td>${esc(c.Updated_At||'—')}</td><td><div class="action-row"><button class="action-btn action-edit" onclick='editConditionCatalogItem(${JSON.stringify(String(c.Condition_ID))})'>Edit</button>${c.Active?`<button class="action-btn action-delete" onclick='deactivateConditionCatalogItem(${JSON.stringify(String(c.Condition_ID))})'>Deactivate</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No conditions loaded. Ensure the ConditionCatalog sheet is migrated and the user is connected.</td></tr>';
}
let editingConditionId='';
function resetConditionEditor(){editingConditionId='';document.getElementById('conditionNameInput').value='';document.getElementById('conditionActiveInput').value='true';document.getElementById('saveConditionBtn').textContent='Save Condition';}
function editConditionCatalogItem(id){const c=conditionCatalog.find(x=>String(x.Condition_ID)===String(id));if(!c)return;editingConditionId=String(id);document.getElementById('conditionNameInput').value=c.Name;document.getElementById('conditionActiveInput').value=c.Active?'true':'false';document.getElementById('saveConditionBtn').textContent='Update Condition';}
async function saveConditionCatalogItem(){
 if(session?.role!=='admin')return;const name=document.getElementById('conditionNameInput').value.trim(),active=document.getElementById('conditionActiveInput').value==='true',btn=document.getElementById('saveConditionBtn'),status=document.getElementById('conditionSaveStatus');
 if(!name){alert('Enter a condition name.');return;}btn.disabled=true;btn.textContent='Saving…';status?.classList.add('visible');
 try{await apiPost('saveCondition',{user:session.user,condition:{Condition_ID:editingConditionId,Name:name,Active:active}});await refreshConditionsLive(false);resetConditionEditor();alert('Condition saved. Admin and BHW forms will use the updated catalog on refresh.');}
 catch(err){alert('Could not save condition.\n\n'+err.message);}
 finally{btn.disabled=false;btn.textContent=editingConditionId?'Update Condition':'Save Condition';status?.classList.remove('visible');}
}
async function deactivateConditionCatalogItem(id){const c=conditionCatalog.find(x=>String(x.Condition_ID)===String(id));if(!c)return;if(!confirm('Deactivate "'+c.Name+'"? Historical patient records will be retained.'))return;try{await apiPost('saveCondition',{user:session.user,condition:{Condition_ID:c.Condition_ID,Name:c.Name,Active:false}});await refreshConditionsLive(false);alert('Condition deactivated; past records are retained.');}catch(err){alert('Could not deactivate condition.\n\n'+err.message);}}

function normHealthFacilityReport(x){
  const history=Array.isArray(x.history)?x.history.map(h=>({id:h.History_ID||h.id||"",action:h.Action||h.action||"",fromStatus:h.From_Status||h.fromStatus||"",toStatus:h.To_Status||h.toStatus||"",remarks:h.Remarks||h.remarks||"",changedBy:h.Changed_By_Username||h.changedBy||"",changedRole:h.Changed_By_Role||h.changedRole||"",changedAt:h.Changed_At||h.changedAt||""})):[];
  return {id:String(x.Report_ID||x.id||""),clientEventId:String(x.Client_Event_ID||x.clientEventId||""),barangay:String(x.Barangay||x.barangay||""),facilityName:String(x.Facility_Name||x.facilityName||""),category:String(x.Category||x.category||""),priority:String(x.Priority||x.priority||"Normal"),title:String(x.Title||x.title||""),description:String(x.Description||x.description||""),bhwId:String(x.Reporting_BHW_ID||x.bhwId||""),bhwName:String(x.Reporting_BHW_Name||x.bhwName||""),bhwUsername:String(x.Reporting_BHW_Username||x.bhwUsername||""),submittedAt:x.Submitted_At||x.submittedAt||"",status:String(x.Status||x.status||"New"),adminRemarks:String(x.Admin_Remarks||x.adminRemarks||""),acknowledgedAt:x.Acknowledged_At||x.acknowledgedAt||"",inProgressAt:x.In_Progress_At||x.inProgressAt||"",resolvedAt:x.Resolved_At||x.resolvedAt||"",updatedAt:x.Updated_At||x.updatedAt||"",history};
}
function populateHealthFacilityFilters(){
  const select=document.getElementById("facilityBarangayFilter");if(!select)return;
  const current=select.value||"all";
  select.innerHTML='<option value="all">All Barangays</option>'+BARANGAYS.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join("");
  select.value=BARANGAYS.includes(current)?current:"all";
}
function renderHealthFacilityReportBadge(summary=healthFacilityReportSummary){
  const badge=document.getElementById("facilityAlertBadge");if(!badge)return;
  const count=Number(summary?.newReports||0);
  badge.textContent=String(count);badge.style.display=count?"inline-flex":"none";
}
async function refreshHealthFacilityReportSummary(showError=false){
  if(session?.role!=="admin")return;
  if(!LIVE_API_URL||!navigator.onLine)return;
  try{
    const data=await apiPost("healthFacilityReportSummary",{user:session.user});
    if(data?.ok!==true)throw new Error(data?.error||"Invalid facility report summary response.");
    healthFacilityReportSummary=data;renderHealthFacilityReportBadge(data);
  }catch(err){
    console.warn("Health facility notification summary refresh failed",err.message);
    if(showError)alert("Could not refresh the new facility report indicator.\n\n"+err.message);
  }
}

function renderHealthFacilityReports(){
  const total=document.getElementById("facilityTotalReports"),newEl=document.getElementById("facilityNewReports"),highEl=document.getElementById("facilityHighReports"),urgentEl=document.getElementById("facilityUrgentReports");
  const open=healthFacilityReports.filter(r=>r.status!=="Resolved");
  if(total)total.textContent=healthFacilityReports.length;
  if(newEl)newEl.textContent=healthFacilityReports.filter(r=>r.status==="New").length;
  if(highEl)highEl.textContent=open.filter(r=>r.priority==="High").length;
  if(urgentEl)urgentEl.textContent=open.filter(r=>r.priority==="Urgent").length;
  const unread=healthFacilityReports.filter(r=>r.status==="New").length;
  healthFacilityReportSummary=Object.assign({},healthFacilityReportSummary||{}, {totalReports:healthFacilityReports.length,newReports:unread,highReports:open.filter(r=>r.priority==="High").length,urgentReports:open.filter(r=>r.priority==="Urgent").length});
  renderHealthFacilityReportBadge(healthFacilityReportSummary);
  const body=document.getElementById("healthFacilityReportBody");if(!body)return;
  const barangay=document.getElementById("facilityBarangayFilter")?.value||"all";
  const status=document.getElementById("facilityStatusFilter")?.value||"all";
  const priority=document.getElementById("facilityPriorityFilter")?.value||"all";
  const q=(document.getElementById("facilityReportSearch")?.value||"").trim().toLowerCase();
  const rows=healthFacilityReports.filter(r=>(barangay==="all"||r.barangay===barangay)&&(status==="all"||r.status===status)&&(priority==="all"||r.priority===priority)&&[r.barangay,r.facilityName,r.category,r.title,r.description,r.bhwName,r.bhwUsername].join(" ").toLowerCase().includes(q));
  body.innerHTML=rows.map(r=>`<tr><td>${esc(formatFacilityDate(r.submittedAt))}</td><td><strong>${esc(r.barangay)}</strong><div class="small-note">${esc(r.facilityName)}</div></td><td><strong>${esc(r.title)}</strong><div class="small-note">${esc(r.category)} • ${esc(truncateFacilityText(r.description,90))}</div></td><td><span class="facility-priority-pill ${facilityPriorityClass(r.priority)}">${esc(r.priority)}</span></td><td>${esc(r.bhwName||r.bhwUsername)}<div class="small-note">${esc(r.bhwUsername)}</div></td><td><span class="facility-status-pill ${facilityStatusClass(r.status)}">${esc(r.status)}</span></td><td><button class="action-btn action-edit" onclick='openHealthFacilityReportDetails(${JSON.stringify(r.id)})'>Review</button></td></tr>`).join("")||'<tr><td colspan="7" class="empty">No health facility reports match this filter.</td></tr>';
}
function formatFacilityDate(value){if(!value)return"—";const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString();}
function truncateFacilityText(value,max){const s=String(value||"");return s.length>max?s.slice(0,max-1)+"…":s;}
async function refreshHealthFacilityReports(showError=false){
  if(session?.role!=="admin")return;
  if(!LIVE_API_URL||!navigator.onLine){if(showError)alert("Health Facility Monitoring requires the live Google Apps Script backend. No report was loaded from localStorage.");return;}
  const body=document.getElementById("healthFacilityReportBody");if(body&&!healthFacilityReports.length)body.innerHTML='<tr><td colspan="7" class="empty">Loading health facility reports from Google Sheets…</td></tr>';
  try{
    const data=await apiPost("healthFacilityReports",{user:session.user});
    if(!Array.isArray(data.reports))throw new Error("The backend did not return a facility report list.");
    healthFacilityReports=data.reports.map(normHealthFacilityReport);
    populateHealthFacilityFilters();renderHealthFacilityReports();
    healthFacilityReportSummary=Object.assign({},healthFacilityReportSummary||{}, {totalReports:healthFacilityReports.length,newReports:healthFacilityReports.filter(r=>r.status==="New").length,highReports:healthFacilityReports.filter(r=>r.status!=="Resolved"&&r.priority==="High").length,urgentReports:healthFacilityReports.filter(r=>r.status!=="Resolved"&&r.priority==="Urgent").length});
    renderHealthFacilityReportBadge(healthFacilityReportSummary);
  }catch(err){console.warn("Health facility reports refresh failed",err.message);if(showError)alert("Could not load Health Facility Monitoring & Alert from Google Sheets.\n\n"+err.message);if(body&&!healthFacilityReports.length)body.innerHTML='<tr><td colspan="7" class="empty">Could not load live facility reports. Check the Apps Script deployment and refresh.</td></tr>';}
}
function openHealthFacilityReportModal(){
  if(session?.role!=="bhw"){alert("Only a logged-in BHW can submit a health facility report.");return;}
  if(!facilityDraftEventId)facilityDraftEventId=makeFacilityClientEventId();
  const assignedBarangay=String(session.barangay||"Assigned barangay").trim();
  const brgy=document.getElementById("facilityReportLockedBarangay");if(brgy)brgy.textContent=assignedBarangay;
  const facilityInput=document.getElementById("hfrFacilityName");if(facilityInput)facilityInput.value=assignedBarangay+" Health Facility";
  document.getElementById("healthFacilityReportModal").style.display="flex";
}
function closeHealthFacilityReportModal(){document.getElementById("healthFacilityReportModal").style.display="none";}
function makeFacilityClientEventId(){return (crypto&&crypto.randomUUID)?crypto.randomUUID():"hfr-"+Date.now()+"-"+Math.random().toString(36).slice(2,12)}
async function submitHealthFacilityReport(){
  if(session?.role!=="bhw"){alert("Only an authorized BHW can submit this report.");return;}
  if(facilityReportSubmitting)return;
  // The displayed facility label is informational; the server independently derives it from the authenticated BHW barangay.
  const facilityName=String(session.barangay||"").trim()+" Health Facility";
  const category=document.getElementById("hfrCategory").value;
  const priority=document.getElementById("hfrPriority").value;
  const title=document.getElementById("hfrTitle").value.trim();
  const description=document.getElementById("hfrDescription").value.trim();
  if(!facilityName||!category||!title||!description){alert("Complete the facility name, category, title, and description.");return;}
  if(description.length<5){alert("Please provide a little more detail about the concern.");return;}
  if(!LIVE_API_URL||!navigator.onLine){alert("The report was not submitted because the live backend is unavailable. Your form remains open. Check the connection and retry; the same submission ID will be reused to prevent duplicates.");return;}
  if(!facilityDraftEventId)facilityDraftEventId=makeFacilityClientEventId();
  facilityReportSubmitting=true;
  const btn=document.getElementById("submitFacilityReportBtn"),cancelBtn=document.getElementById("cancelFacilityReportBtn"),statusBox=document.getElementById("facilityReportSaveStatus"),modal=document.getElementById("healthFacilityReportModal");
  const formControls=modal?Array.from(modal.querySelectorAll("input,select,textarea,button")):[];
  const previousDisabled=formControls.map(el=>el.disabled);
  formControls.forEach(el=>{el.disabled=true});
  if(btn){btn.disabled=true;btn.innerHTML='<span class="inline-loading"><span class="loading-spinner"></span> Sending…</span>';}
  if(statusBox){statusBox.classList.add("visible");statusBox.querySelector("span:last-child").textContent="Submitting report to Google Sheets… Please wait.";}
  try{
    const result=await apiPost("saveHealthFacilityReport",{user:session.user,report:{Client_Event_ID:facilityDraftEventId,Facility_Name:facilityName,Category:category,Priority:priority,Title:title,Description:description}});
    if(result?.ok!==true||result.persisted!==true||!result.report)throw new Error(result?.error||"The backend did not confirm saving this report.");
    const saved=normHealthFacilityReport(result.report);
    document.getElementById("healthFacilityReportModal").style.display="none";
    document.getElementById("hfrFacilityName").value=String(session.barangay||"").trim()+" Health Facility";document.getElementById("hfrCategory").value="";document.getElementById("hfrPriority").value="Normal";document.getElementById("hfrTitle").value="";document.getElementById("hfrDescription").value="";
    facilityDraftEventId="";
    alert((result.duplicate?"This submission was already saved; no duplicate was created. ":"")+"Health facility report saved to Google Sheets and sent to Admin for monitoring.");
    return saved;
  }catch(err){alert("Could not confirm the facility report save. Keep this form open and retry the same submission; do not generate a new report.\n\n"+(err.message||err));}
  finally{
    facilityReportSubmitting=false;
    formControls.forEach((el,i)=>{el.disabled=previousDisabled[i]});
    if(btn){btn.disabled=false;btn.innerHTML="&#x1F4E4; Send to Admin";}
    if(statusBox)statusBox.classList.remove("visible");
  }
}
function openHealthFacilityReportDetails(id){
  if(session?.role!=="admin")return;
  const r=healthFacilityReports.find(x=>String(x.id)===String(id));if(!r)return;
  selectedHealthFacilityReportId=String(r.id);
  document.getElementById("hfrDetailTitle").textContent=r.title||"Health Facility Report";
  document.getElementById("hfrDetailSub").textContent=r.barangay+" • "+r.facilityName+" • Submitted "+formatFacilityDate(r.submittedAt);
  const items=[
    ["Barangay",r.barangay], ["Health Facility",r.facilityName], ["Category",r.category], ["Priority",r.priority],
    ["Report Status",r.status], ["Submitted",formatFacilityDate(r.submittedAt)], ["Reporting BHW",r.bhwName], ["BHW Username",r.bhwUsername],
    ["Concern / Description",r.description,"full"], ["Last Admin Response",r.adminRemarks||"No Admin response yet","full"]
  ];
  document.getElementById("hfrDetailSummary").innerHTML=items.map(([k,v,klass])=>`<div class="facility-detail-item ${klass||""}"><div class="k">${esc(k)}</div><div class="v">${esc(v||"—")}</div></div>`).join("");
  document.getElementById("hfrAdminStatus").value=r.status;document.getElementById("hfrAdminRemarks").value=r.adminRemarks||"";
  renderHealthFacilityReportHistory(r);
  document.getElementById("healthFacilityReportDetailsModal").style.display="flex";
}
function renderHealthFacilityReportHistory(report){
  const list=document.getElementById("hfrHistoryList");if(!list)return;
  list.innerHTML=(report.history||[]).map(h=>`<div class="facility-history-item"><strong>${esc(h.action||"Update")}${h.toStatus?" • "+esc(h.fromStatus? h.fromStatus+" → ":"")+esc(h.toStatus):""}</strong><div class="meta">${esc(h.changedBy||"System")} ${h.changedRole?"("+esc(h.changedRole)+")":""} • ${esc(formatFacilityDate(h.changedAt))}</div>${h.remarks?`<div class="remarks">${esc(h.remarks)}</div>`:""}</div>`).join("")||'<div class="empty">No status history available.</div>';
}
function closeHealthFacilityReportDetails(){document.getElementById("healthFacilityReportDetailsModal").style.display="none";selectedHealthFacilityReportId="";}
async function saveHealthFacilityReportUpdate(){
  if(session?.role!=="admin"||!selectedHealthFacilityReportId||facilityReportUpdating)return;
  if(!LIVE_API_URL||!navigator.onLine){alert("The Admin response was not saved because the live backend is unavailable.");return;}
  const status=document.getElementById("hfrAdminStatus").value,remarks=document.getElementById("hfrAdminRemarks").value.trim();
  facilityReportUpdating=true;const btn=document.getElementById("saveFacilityReportUpdateBtn");if(btn){btn.disabled=true;btn.textContent="Saving…";}
  try{
    const result=await apiPost("updateHealthFacilityReport",{user:session.user,reportId:selectedHealthFacilityReportId,status,remarks});
    if(result?.ok!==true||result.persisted!==true)throw new Error(result?.error||"The backend did not confirm the update.");
    await refreshHealthFacilityReports(false);
    const current=healthFacilityReports.find(x=>String(x.id)===String(selectedHealthFacilityReportId));
    if(current)openHealthFacilityReportDetails(current.id);else closeHealthFacilityReportDetails();
    alert("Facility report status / Admin response saved to Google Sheets.");
  }catch(err){alert("Could not save the Admin response.\n\n"+(err.message||err));}
  finally{facilityReportUpdating=false;if(btn){btn.disabled=false;btn.innerHTML="&#x1F4BE; Save Status / Response";}}
}

function toggleUserBarangayField(){
  const role=document.getElementById("uRole").value;
  const b=document.getElementById("uBarangayField"), h=document.getElementById("uHospitalField");
  if(b)b.style.display=role==="bhw"?"flex":"none";
  if(h)h.style.display=role==="hospital"?"flex":"none";
  document.getElementById("uBarangay").required=role==="bhw";
  const hs=document.getElementById("uHospital");if(hs)hs.required=role==="hospital";
  const pass=document.getElementById("uPassword");if(pass)pass.required=role!=="hospital"&&!editingUserId;
}

