async function saveAdminPatient(){
  if(editingAdminPatientIndex===null||!session||session.role!=="admin")return;
  const r=reports[editingAdminPatientIndex];if(!r){closeAdminPatientEdit();return}
  r.date=document.getElementById("apeDate").value;
  r.name=document.getElementById("apeName").value.trim();
  const editedAgeText=document.getElementById("apeAge").value.trim();
  r.age=editedAgeText===""?"":Number(editedAgeText);
  r.barangay=document.getElementById("apeBarangay").value;
  r.condition=document.getElementById("apeCondition").value;
  r.disposition=document.getElementById("apeDisposition").value;
  r.sex=document.getElementById("apeSex").value;
  r.contact=document.getElementById("apeContact").value.trim();
  r.bp=document.getElementById("apeBp").value.trim();
  r.temp=document.getElementById("apeTemp").value;
  r.hr=document.getElementById("apeHr").value;
  r.rr=document.getElementById("apeRr").value;
  r.o2sat=document.getElementById("apeO2Sat").value;
  r.gcs=document.getElementById("apeGcs").value;
  r.chiefComplaint=document.getElementById("apeChiefComplaint").value.trim();
  r.workingDiagnosis=document.getElementById("apeWorkingDiagnosis").value.trim();
  r.notes=document.getElementById("apeNotes").value.trim();
  r.critical=document.getElementById("apeCritical").checked;
  r.status=r.critical?"Critical":"Review";
  r.syncStatus="queued";r.updatedAt=new Date().toISOString();
  queueForSync(r);save();closeAdminPatientEdit();renderAll();
  let synced=false;if(networkState.online)synced=await syncOutbox();
  if(synced){alert("Patient record updated and saved to Google Sheets.");await refreshAdminHospitalData(false);}
  else alert(networkState.online?"Patient record updated locally but could not be saved to Google Sheets yet. It remains queued for retry.\n\n"+(networkState.lastError||"Check the Apps Script deployment and try Sync again."):"Patient record updated locally and queued for sync until internet returns.");
}

async function deleteAdminPatient(index){
  if(!session||session.role!=="admin")return;
  const r=reports[index];if(!r)return;
  const ok=confirm(`Delete patient record for "${r.name}" from ${r.barangay}?

This action cannot be undone.`);
  if(!ok)return;
  const deleted=r;
  reports.splice(index,1);
  // A delete supersedes any pending create/update for the same record.
  outbox=outbox.filter(x=>String(x.reportId)!==String(deleted.reportId));
  outbox.push({reportId:deleted.reportId,action:"delete",deletedAt:new Date().toISOString(),payload:{...deleted}});
  persistReports();persistOutbox();renderAll();
  let synced=false;if(networkState.online)synced=await syncOutbox();
  if(synced){alert("Patient record deleted from Google Sheets.");}
  else alert(networkState.online?"The record was removed from this view, but deletion has not been confirmed in Google Sheets. It remains queued for retry.\n\n"+(networkState.lastError||"Check the Apps Script deployment and try Sync again."):"The record was removed locally and queued for deletion when internet returns.");
}


