// Prevent overlapping connectivity requests from the Refresh button and auto-refresh.
let connectivityRefreshInFlight=false;
async function refreshUnits(){
  if(connectivityRefreshInFlight)return;
  connectivityRefreshInFlight=true;
  try{
    if(LIVE_API_URL&&navigator.onLine&&session?.role==="admin"){
      try{
        const data=await apiPost('connectivity',{user:session.user});
        if(Array.isArray(data.units)){
          window.__liveConnectivity=data.units;
          applyLiveConnectivity(data.units);
          renderUnits();
          renderAdminDashboardConnectivity();
        }
      }catch(err){console.warn('Connectivity refresh failed',err.message)}
      return;
    }
    applyLiveConnectivity(window.__liveConnectivity||[]);
    renderUnits();
    renderAdminDashboardConnectivity();
  }finally{
    connectivityRefreshInFlight=false;
  }
}

let heartbeatTimer=null;
async function sendBhwHeartbeat(){
  if(!LIVE_API_URL || !navigator.onLine || session?.role!=="bhw") return;
  try{
    const data=await apiPost('heartbeat',{user:session.user,deviceId:DEVICE_ID});
    if(data?.status==="Online"){
      session.user.Last_Seen=data.lastSeen||new Date().toISOString();
      session.user.Device_ID=DEVICE_ID;
    }
  }catch(err){console.warn('BHW heartbeat failed',err.message)}
}
function startBhwHeartbeat(){
  if(heartbeatTimer) clearInterval(heartbeatTimer);
  heartbeatTimer=setInterval(()=>{if(document.visibilityState==="visible")sendBhwHeartbeat()},120000);
  setTimeout(sendBhwHeartbeat,250);
}
function stopBhwHeartbeat(){if(heartbeatTimer){clearInterval(heartbeatTimer);heartbeatTimer=null}}


function queueForSync(report){
  const existing=outbox.find(x=>String(x.reportId)===String(report.reportId));
  if(existing){existing.action='upsert';existing.payload={...report};existing.queuedAt=new Date().toISOString();}
  else outbox.push({reportId:report.reportId,action:'upsert',payload:{...report},queuedAt:new Date().toISOString()});
  report.syncStatus=networkState.online?"syncing":"queued";
  report.syncAttempts=report.syncAttempts||0;
  persistReports();persistOutbox();updateNetworkUI();
}
function isDuplicateReport(candidate){
  const idDup=reports.some(r=>r.reportId===candidate.reportId);
  if(idDup)return true;
  const fp=normalizeForDuplicate(candidate);
  const existing=reports.find(r=>normalizeForDuplicate(r)===fp);
  return !!existing;
}
async function syncOutbox(){
 if(!LIVE_API_URL){networkState.lastError="Google Apps Script Web App URL is not configured.";return false;}
 if(!navigator.onLine){networkState.lastError="Device is offline.";return false;}
 if(!outbox.length)return true;
 if(networkState.syncing||!session){networkState.lastError="Sync is already running or the session is unavailable.";return false;}
 networkState.syncing=true;updateNetworkUI();
 try{
   const queuedAtStart=outbox.slice();
   const result=await apiPost("syncReports",{user:session.user,deviceId:DEVICE_ID,reports:queuedAtStart.map(x=>({action:x.action||"upsert",reportId:x.reportId,payload:x.payload,deviceId:DEVICE_ID}))});
   const good=new Set((result.results||[]).filter(x=>x.ok).map(x=>String(x.reportId)));
   const failed=(result.results||[]).filter(x=>!x.ok);
   outbox=outbox.filter(x=>!good.has(String(x.reportId)));
   reports=reports.map(x=>good.has(String(x.reportId))?Object.assign({},x,{syncStatus:"synced"}):x);
   backendLastSync=new Date().toISOString();persistReports();persistOutbox();
   if(!failed.length){
     // Reload the server's saved rows so the UI cannot claim success while showing a stale local version.
     try{
       const latest=await apiPost('patients',{user:session.user,deviceId:DEVICE_ID});
       if(Array.isArray(latest.patients)){
         const byId=new Map();
         latest.patients.map(normPatient).filter(Boolean).forEach(x=>byId.set(String(x.reportId),x));
         // Keep only still-pending local work over the authoritative rows.
         outbox.forEach(item=>{
           const id=String(item.reportId||'');
           if(item.action==='delete')byId.delete(id);
           else if(item.payload){const pending=normPatient(Object.assign({},item.payload,{syncStatus:'queued'}));if(pending)byId.set(id,pending);}
         });
         reports=Array.from(byId.values());
       }
     }catch(readErr){console.warn('Sync succeeded, but authoritative patient refresh failed',readErr.message);}
   }
   persistReports();persistOutbox();renderAll();
   if(failed.length){networkState.lastError=failed.map(x=>x.error||'Sync failed').join('; ');return false;}
   networkState.lastError='';
   return true;
 }catch(err){networkState.lastError=err.message||"Sync failed";return false}finally{networkState.syncing=false;updateNetworkUI()}
}

function manualSync(){if(networkState.online){syncOutbox();syncAnnouncementOutbox()}else alert("Still offline. Reports and announcements will stay safely queued until the connection returns.");}
window.addEventListener("online",()=>setNetworkOnline(true));
window.addEventListener("offline",()=>setNetworkOnline(false));


function getAgeGroup(age){
  const n=Number(age);
  if(!Number.isFinite(n)) return "Unknown";
  if(n<=17) return "Pedia / Bata";
  if(n<=59) return "Adult";
  return "Matanda / Senior";
}
function demographicCounts(list){
  const gender={Male:0,Female:0,Other:0};
  const ageGroups={"Pedia / Bata":0,Adult:0,"Matanda / Senior":0};
  list.forEach(r=>{
    const g=String(r.sex||"").toLowerCase();
    if(g==="male") gender.Male++;
    else if(g==="female") gender.Female++;
    else gender.Other++;
    ageGroups[getAgeGroup(r.age)]++;
  });
  return {gender,ageGroups};
}
function renderDemographics(target,list){
  const el=document.getElementById(target);if(!el)return;
  const d=demographicCounts(list),total=Math.max(list.length,1);
  const genderRows=[
    ["Male",d.gender.Male,"gender-male"],
    ["Female",d.gender.Female,"gender-female"]
  ];
  const ageRows=[
    ["Pedia / Bata",d.ageGroups["Pedia / Bata"],"age-pedia"],
    ["Adult",d.ageGroups.Adult,"age-adult"]
  ];
  const block=(title,rows)=>`
    <div>
      <div class="panel-sub" style="margin-bottom:9px;font-weight:900;text-transform:uppercase;letter-spacing:.5px">${title}</div>
      <div class="demographic-list">
        ${rows.map(([name,val,cls])=>`<div class="demographic-row">
          <strong>${name}</strong>
          <div class="demographic-track"><span class="${cls}" style="width:${(val/total)*100}%"></span></div>
          <div style="text-align:right;font-weight:950">${val}</div>
        </div>`).join("")}
      </div>
    </div>`;
  el.innerHTML=block("Gender",genderRows)+block("Age Group",ageRows)+
    `<div class="demographic-total"><span>Total recorded</span><strong>${list.length}</strong></div>`;
}


function announcementClass(type){
  return type==="critical"?"announcement-critical":type==="warning"?"announcement-warning":type==="success"?"announcement-success":"announcement-info";
}
function announcementIcon(type){
  return type==="critical"?"\uD83D\uDEA8":type==="warning"?"\u26A0\uFE0F":type==="success"?"\u2705":"\uD83D\uDCE2";
}
function announcementBool(value){
  if(value===undefined||value===null||String(value).trim()==="")return true;
  if(value===true||value===1)return true;
  if(value===false||value===0)return false;
  const s=String(value).trim().toLowerCase();
  return ["true","1","yes","active","published","on"].includes(s);
}
function setAnnouncementPublishLoading(kind,busy){
  const config=kind==="bhw"
    ? {id:"publishBhwAnnouncementBtn",label:"&#x1F4E2; Publish Announcement"}
    : {id:"publishAnnouncementBtn",label:"&#x1F4E2; Publish Announcement"};
  const btn=document.getElementById(config.id);if(!btn)return;
  btn.disabled=!!busy;
  btn.setAttribute("aria-busy",busy?"true":"false");
  btn.innerHTML=busy
    ? '<span class="announcement-button-content"><span class="announcement-spinner" aria-hidden="true"></span> Publishing...</span>'
    : '<span class="announcement-button-content">'+config.label+'</span>';
}
function announcementForBarangay(a,barangay){
  const target=String(a?.barangay||"").trim().toLowerCase().replace(/\s+/g," ");
  const assigned=String(barangay||"").trim().toLowerCase().replace(/\s+/g," ");
  return target==="all barangays"||target==="all"||(!!assigned&&target===assigned);
}
function announcementHasContent(a){return !!(a&&(String(a.id||"").trim()||String(a.title||"").trim()||String(a.body||"").trim()))}
function announcementExpiryMs(value){
  if(!value)return null;
  const s=String(value).trim();
  // The form is date-only. Treat the selected date as valid through 11:59:59 PM local time.
  const m=s.match(/^(\d{4})-(\d{2})-(\d{2})(?:T00:00(?::00(?:\.000)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/);
  if(m){const d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),23,59,59,999);const t=d.getTime();return Number.isFinite(t)?t:null;}
  const t=new Date(value).getTime();return Number.isFinite(t)?t:null;
}
function isAnnouncementExpired(value){
  if(!value)return false;
  const expiry=announcementExpiryMs(value);
  // A malformed/legacy expiry value should not silently hide a valid published alert.
  return expiry!==null&&expiry<Date.now();
}
function allAnnouncements(){
  const map=new Map();
  (announcements||[]).forEach(a=>{if(a&&a.id)map.set(String(a.id),{...a,active:announcementBool(a.active)});});
  (announcementOutbox||[]).forEach(entry=>{
    const a=entry&&entry.announcement;if(a&&a.id)map.set(String(a.id),{...a,pending:true,syncStatus:"queued",active:announcementBool(a.active)});
  });
  return [...map.values()];
}
function activeAnnouncements(){
  return allAnnouncements().filter(a=>announcementBool(a.active)&&!isAnnouncementExpired(a.validUntil));
}
function makeAnnouncementId(){return (crypto&&crypto.randomUUID)?crypto.randomUUID():("ann-"+Date.now()+"-"+Math.random().toString(36).slice(2,12));}
function announcementActorSnapshot(user){
  const out={};["User_ID","Username","Role","Barangay"].forEach(k=>{if(user&&user[k]!==undefined)out[k]=user[k]});return out;
}
function queueAnnouncementForSync(announcement,user){
  const obj={...announcement,id:String(announcement.id||makeAnnouncementId()),active:announcementBool(announcement.active),pending:true,syncStatus:"queued"};
  const entry={id:obj.id,user:announcementActorSnapshot(user),announcement:obj,queuedAt:new Date().toISOString(),attempts:0};
  const idx=announcementOutbox.findIndex(x=>String(x.id)===String(obj.id));
  if(idx>=0)announcementOutbox[idx]=entry;else announcementOutbox.push(entry);
  announcements=[...(announcements||[]).filter(x=>String(x.id)!==String(obj.id)),obj];
  persistAnnouncementOutbox();saveAnnouncements();updateNetworkUI();
  renderPublicAnnouncements();renderAdminAnnouncements();renderAdminDashboardMiniAnnouncements();renderBhwAnnouncements();renderBhwDashboardMiniAnnouncements();
  return obj;
}
function isAnnouncementNetworkFailure(err){return !navigator.onLine||isNetworkLoginError(err);}
async function syncAnnouncementOutbox(){
  if(!LIVE_API_URL||!navigator.onLine||announcementSyncing||!announcementOutbox.length)return;
  announcementSyncing=true;updateNetworkUI();
  try{
    for(const item of [...announcementOutbox]){
      try{
        const result=await apiPost("saveAnnouncement",{user:item.user,announcement:item.announcement});
        if(!result||result.ok!==true)throw new Error(result?.error||"Announcement sync failed.");
        const saved=normAnnouncement(result.announcement||item.announcement);
        saved.pending=false;saved.syncStatus="synced";
        announcementOutbox=announcementOutbox.filter(x=>String(x.id)!==String(item.id));
        announcements=[...(announcements||[]).filter(x=>String(x.id)!==String(item.id)),saved];
        persistAnnouncementOutbox();saveAnnouncements();
      }catch(err){
        item.attempts=Number(item.attempts||0)+1;item.lastError=String(err?.message||err).slice(0,300);
        persistAnnouncementOutbox();
        console.warn("Announcement remains queued",item.id,item.lastError);
        // If offline/network trouble persists, stop this batch and retry on the next online event/refresh.
        break;
      }
    }
  }finally{
    announcementSyncing=false;persistAnnouncementOutbox();updateNetworkUI();
    renderPublicAnnouncements();renderAdminAnnouncements();renderAdminDashboardMiniAnnouncements();renderBhwAnnouncements();renderBhwDashboardMiniAnnouncements();
    if(announcementOutbox.length===0)refreshPublicAnnouncementsLive();
  }
}
function updateAnnouncementFeedMeta(response){
  if(!response||typeof response!="object")return;
  if(response.backendVersion)lastAnnouncementBackendVersion=String(response.backendVersion);
  if(response.diagnostics)lastAnnouncementFeedDiagnostics=response.diagnostics;
}
function announcementDiagnosticsSummary(){
  const d=lastAnnouncementFeedDiagnostics;
  if(!d)return "No feed diagnostics received.";
  return "Backend: "+(lastAnnouncementBackendVersion||d.backendVersion||"unreported")+
    "; sheet: "+(d.sheetName||"Announcements")+
    "; saved rows: "+Number(d.totalRows||0)+
    "; rows with title/body: "+Number(d.rowsWithTitleAndBody||0)+
    "; active: "+Number(d.activeRows||0)+
    "; expired: "+Number(d.expiredRows||0)+
    "; inactive: "+Number(d.inactiveRows||0)+
    "; returned to feed: "+Number(d.returnedRows||0)+
    "; returned to this user: "+Number(d.returnedToUser??d.returnedRows??0);
}
async function showAnnouncementFeedDiagnostics(){
  if(!session||!session.user){alert("Login as Admin or BHW to inspect the announcement feed.");return}
  try{
    const data=await apiPost("announcementDiagnostics",{user:session.user});
    updateAnnouncementFeedMeta(data);
    const entries=(data.entries||[]).map(x=>"• Row "+(x.row||"?")+" / "+(x.id||"no ID")+" — "+(x.title||"(no title)")+" — "+x.reason+"; barangay: "+(x.barangay||"(blank)")+"; Active: "+String(x.active)+"; Valid Until: "+(x.validUntil||"blank")).join("\n");
    alert("ANNOUNCEMENT FEED DIAGNOSTICS\n"+announcementDiagnosticsSummary()+"\n\nRecent rows:\n"+(entries||"No visible/scoped rows returned by diagnostics."));
  }catch(err){alert("Could not read announcement diagnostics. This may mean the deployed Code.gs is older than V46.\n\n"+(err.message||err));}
}
function announcementDiagnosticNotice(){
  if(!session||(session.role!=="admin"&&session.role!=="bhw"))return "";
  if(!lastAnnouncementBackendVersion || lastAnnouncementBackendVersion!==FRONTEND_VERSION){
    return '<div class="notice" style="margin-top:8px;font-size:11px">Feed check: frontend '+esc(FRONTEND_VERSION)+', backend '+esc(lastAnnouncementBackendVersion||"version not reported")+'. Confirm Apps Script was deployed as a new version. <button class="btn btn-light" onclick="showAnnouncementFeedDiagnostics()">Diagnose</button></div>';
  }
  const d=lastAnnouncementFeedDiagnostics;
  if(d && Number(d.totalRows||0)>0 && Number(d.returnedRows||0)===0){
    return '<div class="notice" style="margin-top:8px;font-size:11px">Saved rows exist, but the public feed returned none. <button class="btn btn-light" onclick="showAnnouncementFeedDiagnostics()">Diagnose feed</button></div>';
  }
  return "";
}

function renderPublicAnnouncements(){
  const el=document.getElementById("publicAnnouncementArea");if(!el)return;
  const list=activeAnnouncements().slice().sort((a,b)=>new Date(b.publishedAt||0)-new Date(a.publishedAt||0)).slice(0,3);
  if(!list.length){
    if(publicAnnouncementsLoading&&!publicAnnouncementsLoaded){
      el.innerHTML='<div class="public-announcement-loading"><span class="announcement-spinner" aria-hidden="true"></span> Loading Emergency Alerts &amp; Announcements...</div>';
    }else if(publicAnnouncementsLoadError&&!navigator.onLine){
      el.innerHTML='<div class="public-announcement-empty">Offline. No cached announcements are available on this device.</div>';
    }else if(publicAnnouncementsLoadError){
      el.innerHTML='<div class="public-announcement-empty">Could not refresh announcements. <button class="btn btn-light" style="margin-left:8px" onclick="refreshPublicAnnouncementsLive()">Retry</button></div>';
    }else{
      el.innerHTML='<div class="public-announcement-empty">No current public announcements.</div>'+announcementDiagnosticNotice();
    }
    return;
  }
  el.innerHTML=list.map(a=>`<div class="announcement-banner ${announcementClass(a.type)}" style="margin-bottom:8px">
    <div class="a-left"><div class="a-icon">${announcementIcon(a.type)}</div><div><div class="a-title">${esc(a.title)}</div><div class="a-meta">${esc(a.barangay)} &bull; ${esc(a.priority||"Normal")} &bull; ${a.createdByRole==="bhw"?"BHW":"Admin"} &bull; ${fmtDate(a.publishedAt)}${a.pending?" &bull; PENDING SYNC":""}</div><div class="a-body">${esc(a.body)}</div></div></div>
  </div>`).join("");
}

function renderAdminDashboardMiniAnnouncements(){
  const el=document.getElementById("adminDashboardAnnouncementsMini");if(!el)return;
  const list=activeAnnouncements().slice().sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt)).slice(0,3);
  el.innerHTML=list.map(a=>`<div class="announcement-item"><div class="a-head"><div><div class="a-title">${announcementIcon(a.type)} ${esc(a.title)}</div><div class="a-meta">${esc(a.barangay)} \u2022 ${a.priority} \u2022 ${a.createdByRole==="bhw"?"BHW":"Admin"}</div></div><span class="announcement-dot"></span></div><div class="a-body">${esc(a.body)}</div></div>`).join("")||`<div class="empty">No active announcements.</div>`;
}

function renderAdminAnnouncements(){
  const el=document.getElementById("adminAnnouncementList");if(!el)return;
  el.innerHTML=allAnnouncements().slice().sort((a,b)=>new Date(b.publishedAt)-new Date(a.publishedAt)).map(a=>`<div class="announcement-item">
    <div class="a-head"><div><div class="a-title">${announcementIcon(a.type)} ${esc(a.title)}</div><div class="a-meta">${esc(a.barangay)} \u2022 ${a.priority} \u2022 ${a.createdByRole==="bhw"?"BHW":"Admin"} \u2022 ${fmtDate(a.publishedAt)}</div></div><span class="announcement-status">${a.pending?"Pending Sync":(announcementBool(a.active)?"Published":"Inactive")}</span></div>
    <div class="a-body">${esc(a.body)}</div>
    <div class="action-row" style="margin-top:7px">
      <button class="action-btn action-edit" onclick='editAnnouncement(${JSON.stringify(String(a.id||""))})'>Edit</button>
      <button class="action-btn" style="background:#f8fafc;color:#475569" onclick='toggleAnnouncement(${JSON.stringify(String(a.id||""))})'>${a.active===false?"Publish":"Deactivate"}</button>
      <button class="action-btn action-delete" onclick='deleteAnnouncement(${JSON.stringify(String(a.id||""))})'>Delete</button>
    </div>
  </div>`).join("") || `<div class="empty">No announcements.</div>`;
}

function renderBhwDashboardMiniAnnouncements(){
  if(!session||session.role!=="bhw")return;
  const el=document.getElementById("bhwDashboardAnnouncementsMini");if(!el)return;
  const list=activeAnnouncements().filter(a=>announcementForBarangay(a,session.barangay)).slice(0,2);
  el.innerHTML=list.map(a=>`<div class="announcement-banner ${announcementClass(a.type)}" style="margin-bottom:7px"><div class="a-left"><div class="a-icon">${announcementIcon(a.type)}</div><div><div class="a-title">${esc(a.title)}</div><div class="a-meta">${esc(a.barangay)} \u2022 ${a.priority} \u2022 ${a.createdByRole==="bhw"?"BHW":"Admin"}</div><div class="a-body">${esc(a.body)}</div></div></div></div>`).join("")||`<div class="empty">No active announcements.</div>`;
}


function openBhwAnnouncementModal(){
  if(!session||session.role!=="bhw"){openLogin("bhw");return}
  document.getElementById("baType").value="warning";
  document.getElementById("baPriority").value="Normal";
  document.getElementById("baTitle").value="";
  document.getElementById("baBody").value="";
  document.getElementById("baUntil").value="";
  document.getElementById("baBarangay").value=session.barangay;
  document.getElementById("bhwAnnouncementModal").style.display="flex";
}
function closeBhwAnnouncementModal(){document.getElementById("bhwAnnouncementModal").style.display="none"}
async function saveBhwAnnouncement(){
  if(!session||session.role!=="bhw"||announcementPublishing.bhw)return;
  const title=document.getElementById("baTitle").value.trim();
  const body=document.getElementById("baBody").value.trim();
  if(!title||!body){alert("Title and announcement are required.");return}
  const obj={
    id:makeAnnouncementId(),type:document.getElementById("baType").value,
    priority:document.getElementById("baPriority").value,title,body,
    barangay:session.barangay,validUntil:document.getElementById("baUntil").value,
    publishedAt:new Date().toISOString(),active:true,createdBy:session.username,createdByRole:"bhw"
  };
  announcementPublishing.bhw=true;setAnnouncementPublishLoading("bhw",true);
  try{
    if(!navigator.onLine||!networkState.online){
      queueAnnouncementForSync(obj,session.user);closeBhwAnnouncementModal();
      alert("Saved on this device. Status: PENDING SYNC. It will be published after the connection returns.");return;
    }
    const result=await apiPost("saveAnnouncement",{user:session.user,announcement:obj});
    if(!result||result.ok!==true||result.persisted===false)throw new Error(result?.error||"The backend did not confirm saving this announcement.");
    const saved=normAnnouncement(result.announcement||obj);
    announcements=mergeAnnouncementLists(announcements,[saved]);saveAnnouncements();closeBhwAnnouncementModal();
    let publicConfirmed=false,publicFeedChecked=false,publicFeedError="";
    try{
      const feed=await apiPost("publicAnnouncements",{});
      updateAnnouncementFeedMeta(feed);
      if(Array.isArray(feed.announcements)){
        const remote=feed.announcements.map(normAnnouncement);
        publicFeedChecked=true;
        publicConfirmed=remote.some(a=>String(a.id)===String(saved.id));
        const pending=allAnnouncements().filter(a=>a.pending||a.syncStatus==='queued');
        announcements=mergeAnnouncementLists(remote,pending);
        if(!publicConfirmed)announcements=mergeAnnouncementLists(announcements,[saved]);
        publicAnnouncementsLoaded=true;publicAnnouncementsLoadError=false;
      }else publicFeedError="The public feed returned an invalid response.";
    }catch(feedError){publicFeedError=String(feedError?.message||feedError);console.warn("Public feed verification failed",publicFeedError)}
    try{
      const scoped=await apiPost("announcements",{user:session.user});
      updateAnnouncementFeedMeta(scoped);
      if(Array.isArray(scoped.announcements))announcements=mergeAnnouncementLists(announcements,scoped.announcements.map(normAnnouncement));
    }catch(scopedError){console.warn("BHW announcement refresh failed",scopedError.message)}
    saveAnnouncements();renderPublicAnnouncements();renderBhwAnnouncements();renderBhwDashboardMiniAnnouncements();maybeShowBhwAnnouncementPopup();
    if(publicConfirmed)alert("Announcement saved to Google Sheets and confirmed in the Public Dashboard feed.");
    else if(publicFeedChecked){
      let diagText="";
      try{const diag=await apiPost("announcementDiagnostics",{user:session.user});updateAnnouncementFeedMeta(diag);diagText="\n\n"+announcementDiagnosticsSummary()+"\n\n"+(diag.entries||[]).filter(x=>String(x.id)===String(saved.id)).map(x=>"This announcement: "+x.reason+"; target: "+x.barangay+"; Active: "+String(x.active)+"; Valid Until: "+(x.validUntil||"blank")).join("\n");}catch(diagErr){diagText="\n\nThe deployed backend may not include V46 diagnostics. Check Deploy > Manage deployments > New version.";}
      const serverVersion=lastAnnouncementBackendVersion||"version not reported";
      alert("Google Sheets confirmed the save, but the public feed did not return this announcement. Do not publish it again.\n\nExpected backend: "+FRONTEND_VERSION+"\nReported backend: "+serverVersion+diagText);
    }
    else alert("Announcement was saved to Google Sheets, but feed verification could not finish. Do not publish again. Refresh the page after checking the Apps Script deployment.\n\n"+publicFeedError);
  }catch(err){
    if(isAnnouncementNetworkFailure(err)){
      queueAnnouncementForSync(obj,session.user);closeBhwAnnouncementModal();
      alert("Connection was interrupted. The announcement is saved locally as PENDING SYNC and will retry when online.");return;
    }
    alert("Announcement was saved or published with an error while refreshing the feeds. Do not submit again until you check the Announcements sheet.\\n\\n"+(err.message||err));
  }finally{
    announcementPublishing.bhw=false;setAnnouncementPublishLoading("bhw",false);
  }
}

function renderBhwAnnouncements(){
  if(!session||session.role!=="bhw")return;
  const el=document.getElementById("bhwAnnouncementList");if(!el)return;
  const list=activeAnnouncements().filter(a=>announcementForBarangay(a,session.barangay));
  el.innerHTML=list.map(a=>`<div class="announcement-banner ${announcementClass(a.type)}">
    <div class="a-left"><div class="a-icon">${announcementIcon(a.type)}</div><div><div class="a-title">${esc(a.title)}</div><div class="a-meta">${esc(a.barangay)} \u2022 ${a.priority} \u2022 ${a.createdByRole==="bhw"?"BHW":"Admin"} \u2022 ${fmtDate(a.publishedAt)}${a.pending?" \u2022 PENDING SYNC":""}</div><div class="a-body">${esc(a.body)}</div></div></div>
    ${(a.createdByRole==="bhw"&&String(a.createdBy||"").toLowerCase()===String(session.username||"").toLowerCase())?`<div class="action-row" style="margin-top:8px"><button class="action-btn action-delete" onclick='deleteBhwAnnouncement(${JSON.stringify(String(a.id||""))})'>Delete</button></div>`:""}
  </div>`).join("") || `<div class="empty">No current announcements.</div>`+announcementDiagnosticNotice();
}
function maybeShowBhwAnnouncementPopup(){
  if(!session||session.role!=="bhw")return;
  const list=activeAnnouncements().filter(a=>(a.createdByRole||"admin")==="admin" && announcementForBarangay(a,session.barangay));
  if(!list.length)return;
  const latest=list[0], ackKey="elnino_ack_"+session.username+"_"+latest.id;
  if(localStorage.getItem(ackKey)==="1")return;
  document.getElementById("popupAnnouncementTitle").textContent=latest.title;
  document.getElementById("popupAnnouncementMeta").textContent=`${latest.barangay} \u2022 ${latest.priority} \u2022 ${fmtDate(latest.publishedAt)}`;
  document.getElementById("popupAnnouncementBody").textContent=latest.body;
  document.getElementById("bhwAnnouncementPopup").style.display="flex";
  window.__activePopupAnnouncement=latest;
}
function acknowledgeAnnouncement(){
  const a=window.__activePopupAnnouncement;if(a&&session)localStorage.setItem("elnino_ack_"+session.username+"_"+a.id,"1");
  document.getElementById("bhwAnnouncementPopup").style.display="none";
}
function openAnnouncementModal(){
  if(session?.role!=="admin"){openLogin("admin");return}
  editingAnnouncementId=null;
  document.getElementById("aTitle").value="";
  document.getElementById("aBody").value="";
  document.getElementById("aPriority").value="Normal";
  document.getElementById("aType").value="warning";
  document.getElementById("aUntil").value="";
  document.getElementById("aBarangay").innerHTML='<option value="All Barangays">All Barangays</option>'+BARANGAYS.map(b=>`<option>${b}</option>`).join("");
  document.getElementById("announcementModal").style.display="flex";
}
function closeAnnouncementModal(){document.getElementById("announcementModal").style.display="none";editingAnnouncementId=null}
async function saveAnnouncement(){
  if(session?.role!=="admin"||announcementPublishing.admin)return;
  const title=document.getElementById("aTitle").value.trim(),body=document.getElementById("aBody").value.trim();
  if(!title||!body){alert("Title and announcement are required.");return}
  const obj={
    id:editingAnnouncementId||makeAnnouncementId(),type:document.getElementById("aType").value,
    priority:document.getElementById("aPriority").value,title,barangay:document.getElementById("aBarangay").value,body,
    validUntil:document.getElementById("aUntil").value,publishedAt:new Date().toISOString(),active:true,
    createdBy:session.username,createdByRole:"admin"
  };
  announcementPublishing.admin=true;setAnnouncementPublishLoading("admin",true);
  try{
    if(!navigator.onLine||!networkState.online){
      queueAnnouncementForSync(obj,session.user);closeAnnouncementModal();
      alert("Saved on this device. Status: PENDING SYNC. It will be published after the connection returns.");return;
    }
    const result=await apiPost("saveAnnouncement",{user:session.user,announcement:obj});
    if(!result||result.ok!==true||result.persisted===false)throw new Error(result?.error||"The backend did not confirm saving this announcement.");
    const saved=normAnnouncement(result.announcement||obj);
    announcements=mergeAnnouncementLists(announcements,[saved]);saveAnnouncements();closeAnnouncementModal();
    let publicConfirmed=false,publicFeedChecked=false,publicFeedError="";
    try{
      const feed=await apiPost("publicAnnouncements",{});
      if(Array.isArray(feed.announcements)){
        const remote=feed.announcements.map(normAnnouncement);
        publicFeedChecked=true;
        publicConfirmed=remote.some(a=>String(a.id)===String(saved.id));
        const pending=allAnnouncements().filter(a=>a.pending||a.syncStatus==='queued');
        announcements=mergeAnnouncementLists(remote,pending);
        if(!publicConfirmed)announcements=mergeAnnouncementLists(announcements,[saved]);
        publicAnnouncementsLoaded=true;publicAnnouncementsLoadError=false;
      }else publicFeedError="The public feed returned an invalid response.";
    }catch(feedError){publicFeedError=String(feedError?.message||feedError);console.warn("Public feed verification failed",publicFeedError)}
    try{
      const scoped=await apiPost("announcements",{user:session.user});
      if(Array.isArray(scoped.announcements))announcements=mergeAnnouncementLists(announcements,scoped.announcements.map(normAnnouncement));
    }catch(scopedError){console.warn("Admin announcement refresh failed",scopedError.message)}
    saveAnnouncements();renderAdminAnnouncements();renderAdminDashboardMiniAnnouncements();renderPublicAnnouncements();
    if(publicConfirmed)alert("Announcement saved to Google Sheets and confirmed in the Public Dashboard feed.");
    else if(publicFeedChecked){
      let diagText="";
      try{const diag=await apiPost("announcementDiagnostics",{user:session.user});updateAnnouncementFeedMeta(diag);diagText="\n\n"+announcementDiagnosticsSummary()+"\n\n"+(diag.entries||[]).filter(x=>String(x.id)===String(saved.id)).map(x=>"This announcement: "+x.reason+"; target: "+x.barangay+"; Active: "+String(x.active)+"; Valid Until: "+(x.validUntil||"blank")).join("\n");}catch(diagErr){diagText="\n\nThe deployed backend may not include V46 diagnostics. Check Deploy > Manage deployments > New version.";}
      const serverVersion=lastAnnouncementBackendVersion||"version not reported";
      alert("Google Sheets confirmed the save, but the public feed did not return this announcement. Do not publish it again.\n\nExpected backend: "+FRONTEND_VERSION+"\nReported backend: "+serverVersion+diagText);
    }
    else alert("Announcement was saved to Google Sheets, but feed verification could not finish. Do not publish again. Refresh the page after checking the Apps Script deployment.\n\n"+publicFeedError);
  }catch(err){
    if(isAnnouncementNetworkFailure(err)){
      queueAnnouncementForSync(obj,session.user);closeAnnouncementModal();
      alert("Connection was interrupted. The announcement is saved locally as PENDING SYNC and will retry when online.");return;
    }
    alert("Announcement was saved or published with an error while refreshing the feeds. Do not submit again until you check the Announcements sheet.\\n\\n"+(err.message||err));
  }finally{
    announcementPublishing.admin=false;setAnnouncementPublishLoading("admin",false);
  }
}

function editAnnouncement(id){
  const a=announcements.find(x=>String(x.id)===String(id));if(!a)return;
  editingAnnouncementId=id;
  document.getElementById("aTitle").value=a.title;document.getElementById("aBody").value=a.body;document.getElementById("aPriority").value=a.priority;document.getElementById("aType").value=a.type;document.getElementById("aUntil").value=a.validUntil||"";
  document.getElementById("aBarangay").innerHTML='<option value="All Barangays">All Barangays</option>'+BARANGAYS.map(b=>`<option ${b===a.barangay?"selected":""}>${b}</option>`).join("");
  document.getElementById("announcementModal").style.display="flex";
}
async function toggleAnnouncement(id){
  if(session?.role!=="admin")return;
  const a=announcements.find(x=>String(x.id)===String(id));if(!a)return;
  try{
    const result=await apiPost("saveAnnouncement",{user:session.user,announcement:{id:String(a.id),type:a.type,priority:a.priority,title:a.title,barangay:a.barangay,body:a.body,validUntil:a.validUntil,publishedAt:a.publishedAt,active:a.active===false,createdBy:a.createdBy,createdByRole:a.createdByRole}});
    if(!result||result.ok!==true)throw new Error(result?.error||"Could not update announcement.");
    await refreshLiveState();renderAdminAnnouncements();renderPublicAnnouncements();
  }catch(err){alert("Announcement update failed.\n\n"+(err.message||err))}
}
async function deleteAnnouncement(id){
  if(!session||session.role!=="admin")return;
  if(!confirm("Delete this announcement?"))return;
  try{
    const result=await apiPost("deleteAnnouncement",{user:session.user,announcementId:String(id)});
    if(!result||result.ok!==true)throw new Error(result?.error||"Could not delete announcement.");
    await refreshLiveState();renderAdminAnnouncements();renderPublicAnnouncements();
  }catch(err){alert("Announcement delete failed.\n\n"+(err.message||err))}
}

async function deleteBhwAnnouncement(id){
  if(!session||session.role!=="bhw")return;
  const a=announcements.find(x=>String(x.id)===String(id));
  if(!a)return;
  if(String(a.createdBy||"").toLowerCase()!==String(session.username||"").toLowerCase()){
    alert("You can delete only your own barangay announcement.");return;
  }
  if(!confirm("Delete this BHW announcement?"))return;
  try{
    const result=await apiPost("deleteAnnouncement",{user:session.user,announcementId:String(id)});
    if(!result||result.deleted!==true)throw new Error(result?.error||"Could not delete announcement.");
    announcements=announcements.filter(x=>String(x.id)!==String(id));
    await refreshPublicAnnouncementsLive();
    await refreshLiveState();
    renderBhwAnnouncements();renderBhwDashboardMiniAnnouncements();renderPublicAnnouncements();
    alert("Announcement deleted from Google Sheets.");
  }catch(err){alert("Announcement delete failed.\n\n"+(err.message||err))}
}

function openReleaseInventoryModal(id){
  if(session?.role!=="bhw"){openLogin("bhw");return}
  const item=inventory.find(x=>String(x.id)===String(id)&&String(x.barangay)===String(session.barangay));
  if(!item){alert("Inventory item was not found in your assigned barangay.");return}
  window.__releaseInventoryItem=item;
  document.getElementById("releaseItemName").value=`${item.name} \u2022 ${item.stock} ${item.unit} available`;
  document.getElementById("releasePatientName").value="";
  document.getElementById("releaseQuantity").value="1";
  document.getElementById("releasePatientReportId").value="";
  document.getElementById("releaseReason").value="Patient use / treatment";
  document.getElementById("releaseNotes").value="";
  document.getElementById("releaseInventoryHint").textContent=`Barangay: ${item.barangay} \u2022 Available: ${item.stock} ${item.unit}`;
  document.getElementById("releaseInventoryModal").style.display="flex";
}
function closeReleaseInventoryModal(){document.getElementById("releaseInventoryModal").style.display="none";window.__releaseInventoryItem=null}
async function saveReleaseInventory(){
  const item=window.__releaseInventoryItem;if(!item||!session||session.role!=="bhw")return;
  const patientName=document.getElementById("releasePatientName").value.trim();
  const quantity=Number(document.getElementById("releaseQuantity").value||0);
  if(!patientName){alert("Patient name is required.");return}
  if(!Number.isFinite(quantity)||quantity<=0){alert("Quantity must be greater than zero.");return}
  if(quantity>Number(item.stock||0)){alert(`Insufficient stock. Only ${item.stock} ${item.unit} is available.`);return}
  const btn=document.getElementById("releaseInventoryBtn");if(btn?.dataset.saving==="1")return;
  const clientEventId=(crypto?.randomUUID?crypto.randomUUID():(Date.now()+"-"+Math.random().toString(16).slice(2)));
  try{
    if(btn){btn.dataset.saving="1";btn.disabled=true;btn.textContent="\u23F3 Releasing\u2026";}
    const result=await apiPost("releaseInventory",{user:session.user,inventoryId:String(item.id),quantity,patientName,patientReportId:document.getElementById("releasePatientReportId").value.trim(),reason:document.getElementById("releaseReason").value.trim(),notes:document.getElementById("releaseNotes").value.trim(),clientEventId});
    if(!result||result.persisted!==true)throw new Error(result?.error||"The server did not confirm the release.");
    if(result.inventory){
      const updated=normInventory(result.inventory);
      inventory=[...inventory.filter(x=>String(x.id)!==String(updated.id)),updated];
      persistInventoryLive();
    }
    closeReleaseInventoryModal();
    renderBhwInventory();
    if(currentView==="bhw") renderBhw();
    // The API response already contains the authoritative saved stock.
    // Refresh Google Sheets in the background instead of blocking the UI.
    setTimeout(()=>{ refreshBhwInventoryLive().catch(()=>{}); },250);
    alert(`${quantity} ${item.unit} of ${item.name} released to ${patientName}. Available stock is now ${normInventory(result.inventory||{}).stock} ${item.unit}.`);
  }catch(err){alert("Inventory release failed.\n\n"+(err.message||err))}
  finally{if(btn){btn.dataset.saving="0";btn.disabled=false;btn.textContent="\uD83D\uDCE4 Confirm Release"}}
}

function stockClass(item){
  if(Number(item.stock)<=Number(item.reorder)) return "stock-critical";
  if(Number(item.stock)<=Number(item.reorder)*2) return "stock-low";
  return "stock-good";
}
const CENTRAL_STOCK = "CITY CENTRAL STOCK";
function isCentralStock(item){const b=String(item?.barangay||"").trim().toUpperCase();return b===CENTRAL_STOCK||b==="CITY CENTRAL STOCK";}
function inventoryActionId(id){return JSON.stringify(String(id||""))}
function renderAdminInventory(){
  const el=document.getElementById("adminInventoryGrid");if(!el)return;
  const bf=document.getElementById("invBarangayFilter").value,cf=document.getElementById("invCategoryFilter").value;
  const list=[...inventory]
    .filter(i=>(bf==="all"||i.barangay===bf)&&(cf==="all"||i.category===cf))
    .sort((a,b)=>(isCentralStock(b)-isCentralStock(a))||String(a.name).localeCompare(String(b.name))||String(a.barangay).localeCompare(String(b.barangay)));
  const central=inventory.filter(isCentralStock);
  const centralStock=central.reduce((s,i)=>s+Number(i.stock||0),0);
  const distributed=central.reduce((s,i)=>s+Number(i.released||0),0);
  const low=central.filter(i=>Number(i.stock)<=Number(i.reorder)).length;
  document.getElementById("invItemCount").textContent=central.length;
  document.getElementById("invStockTotal").textContent=centralStock;
  document.getElementById("invReleasedTotal").textContent=distributed;
  document.getElementById("invLowCount").textContent=low;
  el.innerHTML=list.map(i=>{
    const centralRow=isCentralStock(i),idArg=inventoryActionId(i.id),location=centralRow?"Central Warehouse":i.barangay;
    const actions=centralRow
      ? `<button class="action-btn action-edit" onclick='editInventoryItem(${idArg})'>Edit Stock</button><button class="action-btn action-edit" onclick='openDistributeInventoryModal(${idArg})'>Distribute</button><button class="action-btn action-delete" onclick='deleteInventoryItem(${idArg})'>Delete</button>`
      : `<span class="chip" style="font-size:9px">Distributed Stock \u2022 Admin controlled</span>`;
    return `<div class="inventory-card"><div class="inventory-top"><div><div class="inventory-name">${esc(i.name)}</div><div class="inventory-category">${esc(i.category)} \u2022 ${esc(location)}</div></div><span class="status ${Number(i.stock)<=Number(i.reorder)?"s-critical":"s-open"}">${Number(i.stock)<=Number(i.reorder)?"LOW":"OK"}</span></div>
      <div class="stock-number">${i.stock}<span class="stock-unit">${esc(i.unit)}</span></div><div class="stock-bar"><span class="${stockClass(i)}" style="width:${Math.min(100,(Number(i.stock)/(Math.max(Number(i.reorder)*4,1)))*100)}%"></span></div>
      <div class="inventory-meta"><div><small>${centralRow?"Distributed":"Received"}</small><strong>${centralRow?i.released:0}</strong></div><div><small>Reorder Level</small><strong>${i.reorder}</strong></div></div>
      <div class="action-row" style="margin-top:8px;flex-wrap:wrap">${actions}</div></div>`;
  }).join("")||`<div class="empty" style="grid-column:1/-1">No inventory items found.</div>`;
}
