  document.getElementById("inventoryModalTitle").textContent=editingInventoryId?"Edit Central Stock":"Add Central Stock";
  const item=editingInventoryId?inventory.find(i=>String(i.id)===editingInventoryId):null;
  document.getElementById("iCategory").value=item?.category||"First Aid";document.getElementById("iName").value=item?.name||"";document.getElementById("iUnit").value=item?.unit||"pieces";
  document.getElementById("iStock").value=Number(item?.stock||0);document.getElementById("iReorder").value=Number(item?.reorder||5);document.getElementById("inventoryModal").style.display="flex";
