async function saveInventoryItem(){
  if(session?.role!=="admin"){alert("Admin access required.");return}
  const saveBtn=[...document.querySelectorAll("#inventoryModal button")].find(b=>String(b.textContent||"").includes("Save Central Stock"));
  if(saveBtn?.dataset.saving==="1") return;
  const obj={id:editingInventoryId||"",barangay:CENTRAL_STOCK,category:document.getElementById("iCategory").value,name:document.getElementById("iName").value.trim(),unit:document.getElementById("iUnit").value.trim(),stock:Number(document.getElementById("iStock").value||0),reorder:Number(document.getElementById("iReorder").value||0),released:editingInventoryId?Number(inventory.find(i=>String(i.id)===String(editingInventoryId))?.released||0):0,clientEventId:(crypto?.randomUUID?crypto.randomUUID():(Date.now()+"-"+Math.random().toString(16).slice(2)))};
  if(!obj.name||!obj.unit){alert("Item name and unit are required.");return} if(obj.stock<0||obj.reorder<0){alert("Stock and reorder level cannot be negative.");return}
  try{
    if(saveBtn){saveBtn.dataset.saving="1";saveBtn.disabled=true;saveBtn.textContent="\u23F3 Saving\u2026";}
    const result=await apiPost("saveInventory",{user:session.user,inventory:obj});
    if(!result || result.persisted!==true) throw new Error("The server did not confirm the stock was written to Google Sheets.");
    await refreshLiveState();
    closeInventoryModal();
    renderAll();
    const message=result.merged
      ? `Central stock updated. Existing ${obj.name} stock was consolidated instead of creating a duplicate row.`
      : "Central stock saved to Google Sheets.";
    alert(message);
  } catch(err){
    alert("Central stock was not saved.\n\n"+err.message);
  } finally {
    if(saveBtn){saveBtn.dataset.saving="0";saveBtn.disabled=false;saveBtn.textContent="\uD83D\uDCBE Save Central Stock";}
  }
}
function editInventoryItem(id){openInventoryModal(id)}
async function deleteInventoryItem(id){
  const item=inventory.find(i=>String(i.id)===String(id));if(!item)return;
  if(!isCentralStock(item)){alert("Barangay stock can only be changed through distribution.");return}
  const remaining=Number(item.stock||0);
  const warning=remaining>0
    ? `\n\nWARNING: ${remaining} ${item.unit} is still in Central Warehouse.\nDeleting will remove this central stock record; it will not erase past distribution transaction history.\n\nContinue?`
    : "";
  if(!confirm(`Delete ${item.name} from Central Warehouse?${warning}`))return;
  try{
    const result=await apiPost("deleteInventory",{user:session.user,inventoryId:String(id)});
    if(result?.deleted!==true) throw new Error("The server did not confirm deletion.");
    inventory=inventory.filter(i=>String(i.id)!==String(id));persistInventoryLive();await refreshLiveState();renderAll();
    alert(`${item.name} was deleted from Central Warehouse.`);
  }catch(err){alert("Inventory was not deleted.\n\n"+err.message)}
}
