async function saveDistribution(){
  if(session?.role!=="admin"){alert("Admin access required.");return}
  const inventoryId=String(document.getElementById("dInventoryItem").value||""),barangay=document.getElementById("dBarangay").value,quantity=Number(document.getElementById("dQuantity").value||0),notes=document.getElementById("dNotes").value.trim();
  const source=inventory.find(i=>String(i.id)===inventoryId&&isCentralStock(i));
  if(!source){alert("Select a valid Central Warehouse stock item.");return} if(!barangay||BARANGAYS.indexOf(barangay)<0){alert("Select a valid barangay.");return}
  if(!Number.isFinite(quantity)||quantity<=0){alert("Quantity must be greater than zero.");return} if(quantity>Number(source.stock||0)){alert(`Insufficient central stock. Only ${source.stock} ${source.unit} is available.`);return}
  try{const result=await apiPost("distributeInventory",{user:session.user,inventoryId,barangay,quantity,notes});if(result.central)inventory=[...inventory.filter(i=>String(i.id)!==String(result.central.Inventory_ID||result.central.id)),normInventory(result.central)];if(result.target)inventory=[...inventory.filter(i=>String(i.id)!==String(result.target.Inventory_ID||result.target.id)),normInventory(result.target)];persistInventoryLive();closeDistributeInventoryModal();await refreshLiveState();alert(`Distributed ${quantity} ${source.unit} of ${source.name} to ${barangay}.`);}
  catch(err){alert("Distribution failed.\n\n"+err.message)}
}
