async function refreshLiveState(){
  if(!LIVE_API_URL||!navigator.onLine||liveRefreshing)return;
  liveRefreshing=true;
  try{
    const payload=session&&session.user?{user:session.user,deviceId:DEVICE_ID}:{};
    const requestList=[apiPost("dashboard",payload)];
    if(session&&session.user&&(session.role==="admin"||session.role==="bhw")) requestList.push(apiPost("announcements",{user:session.user,activeOnly:false}));
    else requestList.push(apiPost("publicAnnouncements",{}));
    const [data,announcementFeed]=await Promise.all(requestList);
    updateAnnouncementFeedMeta(announcementFeed);
    if(Array.isArray(data.patients)) reports=data.patients.map(normPatient).filter(Boolean);
    const authoritativeAnnouncements=Array.isArray(announcementFeed.announcements)
      ? announcementFeed.announcements.map(normAnnouncement)
      : (Array.isArray(data.announcements) ? data.announcements.map(normAnnouncement) : null);
    if(authoritativeAnnouncements){
      const pendingAnnouncements=allAnnouncements().filter(a=>a.pending||a.syncStatus==="queued");
      announcements=mergeAnnouncementLists(authoritativeAnnouncements,pendingAnnouncements);
      saveAnnouncements();
    }
    if(Array.isArray(data.inventory)) inventory=data.inventory.map(normInventory);
    if(Array.isArray(data.personnel)) users=data.personnel.map(normUser);
    // User Management needs all admin/BHW accounts, including inactive accounts.
    if(session?.role==="admin"){
      try{
        const userData=await apiPost("users",{user:session.user});
        if(Array.isArray(userData.users)) users=userData.users.map(normUser);
      }catch(userErr){ console.warn("User Management refresh failed",userErr.message); }
    }
    if(Array.isArray(data.heatIndex)) heatIndexData=data.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
    heatReference=data.referenceStation||null;
    renderHeatReference();
    window.__liveConnectivity=Array.isArray(data.connectivity)?data.connectivity:[];
    applyLiveConnectivity(window.__liveConnectivity);
    backendLastSync=new Date().toISOString();
    renderAll();
    updateNetworkUI();
  }catch(err){console.warn("Live refresh failed",err.message)}
  finally{liveRefreshing=false}
}
function startAutoRefresh(){
 if(liveRefreshTimer)clearInterval(liveRefreshTimer);
 liveRefreshTimer=setInterval(()=>{
   if(document.visibilityState!=="visible")return;
   refreshCurrentViewData();
   if(currentView==='public')refreshPublicConditionCatalog(false);
   if(currentView==='public')refreshPublicBranding(false,false);
   if(session&&(session.role==='admin'||session.role==='bhw'))refreshConditionsLive(false);
 },currentView==="hospital-dashboard"?15000:LIVE_REFRESH_MS);
}
// Connectivity now uses the existing 30-second active-view refresh only.
// refreshUnits() is single-flight to avoid duplicate simultaneous requests.
document.addEventListener("visibilitychange",()=>{
 if(document.visibilityState==="visible"){
   refreshCurrentViewData();
   if(currentView==='public')refreshPublicConditionCatalog(false);
   if(currentView==='public')refreshPublicBranding(false,false);
   if(session?.role==="admin"||session?.role==="bhw")refreshConditionsLive(false);
   if(session?.role==="bhw") sendBhwHeartbeat();
 }
});

