function rptRenderBarangayCompare(curList,prevList){
  const rows=BARANGAYS.map(b=>{const c=curList.filter(r=>r.barangay===b).length,p=prevList.filter(r=>r.barangay===b).length,delta=c-p,pct=p?((delta/p)*100):c?100:0;return {b,c,p,delta,pct};});
  rows.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||b.c-a.c||a.b.localeCompare(b.b));
  const body=document.getElementById("rptBarangayCompareBody");if(!body)return;
  body.innerHTML=rows.map(x=>{const cls=x.delta>0?'report-up':x.delta<0?'report-down':'report-flat';const sign=x.delta>0?'+':'';return `<tr><td><strong>${esc(x.b)}</strong></td><td>${x.c}</td><td>${x.p}</td><td class="${cls}">${sign}${x.delta}</td><td class="${cls}">${x.pct>0?'+':''}${x.pct.toFixed(1)}%</td></tr>`}).join("");
  const inc=[...rows].filter(x=>x.delta>0).sort((a,b)=>b.delta-a.delta||b.pct-a.pct)[0];const badge=document.getElementById("rptTopIncrease");if(badge)badge.textContent=inc?`Highest increase: ${inc.b} (+${inc.delta})`:'Highest increase: \u2014';
}
function rptPeriodLabel(mode,start,end){const label=mode==="this-week"?'This Week':mode==="previous-week"?'Previous Week':mode==="this-month"?'This Month':mode==="previous-month"?'Previous Month':mode==="last-7"?'Last 7 Days':mode==="last-30"?'Last 30 Days':'Custom Range';return `${label} \u2022 ${start.toLocaleDateString()} \u2013 ${end.toLocaleDateString()}`;}
