  const mode=document.getElementById("rptPeriod")?.value||"this-week";const [start,end]=rptBounds(mode),[prevStart,prevEnd]=rptPrevBounds(start,end);
  const brgy=document.getElementById("rptBarangay")?.value||"all",condition=document.getElementById("rptCondition")?.value||"all";
  const base=rptFilterList(reports,brgy,condition),current=base.filter(r=>rptInBounds(r,start,end)),previous=base.filter(r=>rptInBounds(r,prevStart,prevEnd));
  const total=current.length,prevTotal=previous.length,critical=current.filter(r=>r.status==="Critical"||r.critical).length,review=current.filter(r=>r.status==="Review").length,reportingBarangays=new Set(current.map(r=>r.barangay)).size;
  const pct=prevTotal?((total-prevTotal)/prevTotal)*100:(total?100:0),changeEl=document.getElementById("rptChange");
  document.getElementById("rptTotalCases").textContent=total;document.getElementById("rptCritical").textContent=critical;document.getElementById("rptBarangays").textContent=reportingBarangays;changeEl.textContent=(pct>0?'+':'')+pct.toFixed(1)+'%';changeEl.style.color=pct>0?'#b91c1c':pct<0?'#166534':'#64748b';document.getElementById("rptChangeNote").textContent=`Previous period: ${prevTotal} cases`;
  document.getElementById("rptPeriodNotice").textContent=`${rptPeriodLabel(mode,start,end)} \u2022 Compared with ${prevStart.toLocaleDateString()} \u2013 ${prevEnd.toLocaleDateString()}`;
  rptRenderDaily(rptEntriesByDay(current,start,end));rptRenderCompare(total,prevTotal,"Selected Period","Previous Period");rptRenderHBars("rptConditionChart",rptCountBy(current,r=>r.condition));rptRenderHBars("rptDispositionChart",rptCountBy(current,r=>r.disposition||"Not specified"));rptRenderBarangayCompare(current,previous);
