// BHW/Admin login: online verification is preferred. If the device has previously
// authenticated successfully, a network failure/airplane mode can use the local verifier.
function applyAuthenticatedUser(u,offline=false,sessionToken=""){
 const role=String(u.Role||"").toLowerCase();
 if(role==="hospital"&&offline)throw new Error("Hospital dashboard requires online verification.");
 session={role:role,username:u.Username,barangay:role==="bhw"?u.Barangay:null,hospitalId:role==="hospital"?u.Hospital_ID||"":null,user:u,sessionToken:String(sessionToken||u.sessionToken||""),offline:!!offline};
 // Keep the verified session only for this browser tab so a page refresh does not log the user out.
 // sessionStorage clears when the tab/window is closed; no password is stored.
 try{if(!offline&&session.sessionToken)sessionStorage.setItem(PERSISTED_TAB_SESSION_KEY,JSON.stringify({user:u,sessionToken:session.sessionToken,savedAt:Date.now()}));}catch(_){ }
 closeLogin();
 const roleLabel=role==="admin"?"ADMIN":role==="bhw"?`BHW • ${session.barangay}`:`HOSPITAL • ${hospitalNameById(session.hospitalId)||session.hospitalId}`;
 document.getElementById("sideUser").textContent=roleLabel.toUpperCase();
 document.getElementById("sideBrgy").textContent=role==="admin"?"All barangays":role==="bhw"?session.barangay:(hospitalNameById(session.hospitalId)||"Assigned hospital");
 document.getElementById("sessionChip").textContent=offline?(role==="admin"?"Admin Access • Offline":`BHW • Offline`):(role==="admin"?"Admin Access":role==="bhw"?`BHW • ${session.barangay}`:"Hospital Access");
 document.getElementById("logoutBtn").classList.remove("hidden");
 applyRoleNavigation();
 const initialView=role==="admin"?"admin":role==="bhw"?"bhw":"hospital-dashboard";
 showView(initialView);
 if(role==="bhw"&&!offline)startBhwHeartbeat();
 if(!offline){
   setTimeout(()=>refreshModuleLive(initialView),0);
   if(role==="admin"||role==="bhw")setTimeout(()=>refreshConditionsLive(false),50);
 }
 if(role==="bhw"&&!offline)setTimeout(maybeShowBhwAnnouncementPopup,250);
 if(role==="hospital"&&String(u.Must_Change_Password).toLowerCase()==="true")setTimeout(()=>openHospitalPasswordModal(true),120);
}
function isNetworkLoginError(err){
 const m=String(err?.message||err||"").toLowerCase();
 return m.includes("failed to fetch") || m.includes("networkerror") || m.includes("network error") || m.includes("timed out") || m.includes("timeout") || m.includes("load failed");
}

async function login(){
 const role=document.getElementById("loginRole").value;
 const username=document.getElementById("loginUser").value.trim();
 const password=document.getElementById("loginPass").value;
 const btn=document.getElementById("loginSubmitBtn");
 if(!username||!password){document.getElementById("loginError").textContent="Enter username and password.";document.getElementById("loginError").style.display="block";return}
 if(btn){btn.disabled=true;btn.textContent="Signing in\u2026"}
 try{
   // Airplane mode/offline: authenticate against the verifier created by a previous online login.
   if(!navigator.onLine){
     if(role==="hospital") throw new Error("Hospital accounts must sign in online.");
     if(!readOfflineAuth()) throw new Error("No offline login is stored on this device yet. Connect to the internet and sign in once first.");
     const cached=await tryOfflineLogin(username,password,role);
     if(!cached) throw new Error("No offline login is stored for this account on this device.");
     applyAuthenticatedUser(cached.user,true,cached.sessionToken);
     return;
   }

   if(!LIVE_API_URL){
     const cached=readOfflineAuth();
     if(cached){const offline=await tryOfflineLogin(username,password,role);if(offline){applyAuthenticatedUser(offline.user,true,offline.sessionToken);return;}}
     throw new Error("Live backend is not connected. Add the Code.gs Web App URL first.");
   }

   try{
     const cachedForFastPath=readOfflineAuth();
     const loginRequest=apiPost("login",{username:username,password:password,deviceId:DEVICE_ID,requestedRole:role,hospitalId:role==="hospital"?selectedHospitalLoginId:""});
     let result;

     // Returning users get a fast fallback after 6 seconds. The real online request
     // continues in the background, so a slow Apps Script response does not block the UI.
     if(cachedForFastPath && offlineAuthKey(cachedForFastPath.username)===offlineAuthKey(username) && String(cachedForFastPath.role||"").toLowerCase()===String(role||"").toLowerCase()){
       const FAST_LOGIN_MS=6000;
       const timedOut=Symbol("login-timeout");
       result=await Promise.race([
         loginRequest,
         new Promise(resolve=>setTimeout(()=>resolve(timedOut),FAST_LOGIN_MS))
       ]);
       if(result===timedOut){
         const offline=await tryOfflineLogin(username,password,role);
         if(offline){
           applyAuthenticatedUser(offline.user,true,offline.sessionToken);
           const e=document.getElementById("loginError");
           if(e){e.textContent="Offline access: last online verification is still valid. Online sync will continue in the background.";e.style.display="block";e.style.background="#eff6ff";e.style.color="#1e40af";}
           loginRequest.then(async live=>{try{if(live&&live.sessionToken){await cacheOfflineAuth(password,live.user,live.sessionToken);if(session&&session.username===live.user.Username){session.sessionToken=live.sessionToken||session.sessionToken;session.offline=false;}}}catch(_){}}).catch(_=>{});
           return;
         }
         result=await loginRequest;
       }
     }else{
       result=await loginRequest;
     }

     if(!result||!result.sessionToken)throw new Error("The Apps Script backend is older than this test frontend. Deploy the updated Code.gs as a new Web App version, then sign in again.");
     const u=result.user;
     if(String(u.Role||"").toLowerCase()!==role)throw new Error("This account is not authorized for the selected dashboard.");
     if(role==="hospital"&&selectedHospitalLoginId&&String(u.Hospital_ID||"")!==selectedHospitalLoginId)throw new Error("This account is assigned to a different hospital.");
     if(role!=="hospital")await cacheOfflineAuth(password,u,result.sessionToken);
     applyAuthenticatedUser(u,false,result.sessionToken);
   }catch(err){
     // If Apps Script is temporarily slow/unreachable, a previously verified device can still open
     // the app offline instead of being blocked by a transient network error. Server-side auth errors
     // (wrong password, inactive account, etc.) are never bypassed.
     if(isNetworkLoginError(err)){
       const offline=await tryOfflineLogin(username,password,role);
       if(offline){
         applyAuthenticatedUser(offline.user,true,offline.sessionToken);
         const e=document.getElementById("loginError");
         if(e){e.textContent="Offline access: last online verification is still valid.";e.style.display="block";e.style.background="#eff6ff";e.style.color="#1e40af";}
         return;
       }
     }
     throw err;
   }
 }catch(err){
   const e=document.getElementById("loginError");
   e.textContent=err.message||"Login failed.";e.style.display="block";e.style.background="";e.style.color="";
 }finally{if(btn){btn.disabled=false;btn.textContent="Login"}}
}
