const DEFAULT_PUBLIC_BRANDING = {
 title:'SUPER EL NIÑO',
 kicker:'Heat Alert Monitoring • Community Health Surveillance',
 description:'Public situation dashboard for heat-related illness reports.',
 actions:[
  {icon:'☀',label:'Heat Response',target:'heat',url:''},
  {icon:'📍',label:'Barangay Tally',target:'tally',url:''},
  {icon:'🏥',label:'Community Reports',target:'reports',url:''}
 ]
};
const BRANDING_TARGETS = {
 heat:'publicHeatMonitoring', tally:'publicBarangayTally', reports:'publicSituationDashboard',
 announcements:'publicAnnouncementsAnchor', hospitals:'publicHospitalsPanel', top:'view-public'
};
let publicBrandingUpdatedAt = '';
let publicBrandingLoading = false;
let selectedBrandingClearLogo = false;

function cleanBrandingActions(actions){
 const input=Array.isArray(actions)?actions:DEFAULT_PUBLIC_BRANDING.actions;
 return input.slice(0,3).map(function(a,i){
   const fallback=DEFAULT_PUBLIC_BRANDING.actions[i]||{icon:'',label:'',target:'reports',url:''};
   const target=String(a&&a.target||fallback.target);
   return {
     icon:String(a&&a.icon!==undefined?a.icon:fallback.icon).trim().slice(0,8),
     label:String(a&&a.label!==undefined?a.label:fallback.label).trim().slice(0,36),
     target:Object.prototype.hasOwnProperty.call(BRANDING_TARGETS,target)||target==='external'?target:fallback.target,
     url:String(a&&a.url||'').trim().slice(0,500)
   };
 });
}
function addBrandingActionElements(container, actions, previewOnly){
 if(!container)return;
 container.replaceChildren();
 cleanBrandingActions(actions).forEach(function(action){
   if(!action.label)return;
   const link=document.createElement('a');
   link.className='hero-tag hero-tag-anchor';
   link.textContent=(action.icon?action.icon+' ':'')+action.label;
   link.setAttribute('aria-label',action.label);
   if(action.target==='external'){
     if(!/^https:\/\//i.test(action.url))return;
     try{const u=new URL(action.url);if(u.protocol!=='https:')return;}catch(e){return;}
     link.href=action.url;link.target='_blank';link.rel='noopener noreferrer';
   }else{
     const id=BRANDING_TARGETS[action.target]||BRANDING_TARGETS.reports;
     link.href='#'+id;
     link.addEventListener('click',function(event){
       if(previewOnly){event.preventDefault();return;}
       const target=document.getElementById(id);
       if(!target)return;
       event.preventDefault();
       target.scrollIntoView({behavior:'smooth',block:'start'});
     });
   }
   if(previewOnly)link.addEventListener('click',function(event){event.preventDefault();});
   container.appendChild(link);
 });
}
