async function refreshPublicAnnouncementsLive(){
  if(!LIVE_API_URL||!navigator.onLine){
    publicAnnouncementsLoading=false;
    if(!publicAnnouncementsLoaded)publicAnnouncementsLoadError=true;
    renderPublicAnnouncements();
    return;
  }
  publicAnnouncementsLoading=true;
  publicAnnouncementsLoadError=false;
  renderPublicAnnouncements();
  try{
    const data=await apiPost('publicAnnouncements',{});
    updateAnnouncementFeedMeta(data);
    if(!Array.isArray(data.announcements))throw new Error('The public announcement feed did not return an announcement list.');
    const remote=data.announcements.map(normAnnouncement);
    const pending=allAnnouncements().filter(a=>a.pending||a.syncStatus==='queued');
    announcements=mergeAnnouncementLists(remote,pending);
    publicAnnouncementsLoaded=true;
    publicAnnouncementsLoadError=false;
    saveAnnouncements();
  }catch(err){
    publicAnnouncementsLoadError=true;
    console.warn('Public announcements refresh failed',err.message);
  }finally{
    publicAnnouncementsLoading=false;
    renderPublicAnnouncements();
    renderBhwAnnouncements();
    renderBhwDashboardMiniAnnouncements();
  }
}

