async function refreshModuleLive(view=currentView){
  if(!LIVE_API_URL || !navigator.onLine) return;
  try{
    if(view==='public'){
      if(!publicAnnouncementsLoaded){publicAnnouncementsLoading=true;renderPublicAnnouncements();}
      const [dash,ann,hospitals]=await Promise.all([
        apiPost('dashboard',{}),
        apiPost('publicAnnouncements',{}),
        apiPost('publicHospitals',{})
      ]);
      updateAnnouncementFeedMeta(ann);
      updateAnnouncementFeedMeta(dash);
      if(Array.isArray(dash.patients)) reports=dash.patients.map(normPatient).filter(Boolean);
      if(Array.isArray(dash.heatIndex)) heatIndexData=dash.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
      heatReference=dash.referenceStation||heatReference;
      if(Array.isArray(ann.announcements)){
        const remote=ann.announcements.map(normAnnouncement);
        const pending=allAnnouncements().filter(a=>a.pending||a.syncStatus==='queued');
        announcements=mergeAnnouncementLists(remote,pending);saveAnnouncements();
      }
      publicAnnouncementsLoaded=true;publicAnnouncementsLoading=false;publicAnnouncementsLoadError=false;
      publicHospitals=Array.isArray(hospitals.hospitals)?hospitals.hospitals:[];hospitalRegistry=publicHospitals.slice();
      renderPublic();renderPublicAnnouncements();renderPublicHeat();renderPublicHospitals();return;
    }
    if(view==='admin'){
      await Promise.all([refreshLiveState(),refreshBhwRegistrationSummary(false),refreshHealthFacilityReportSummary(false),refreshAdminHospitalData(false),refreshConditionsLive(false)]);
      return;
    }
    if(view==='admin-conditions'){
      await refreshConditionsLive(false);return;
    }
    if(view==='admin-hospitals'){
      await refreshAdminHospitalData(false);return;
    }
    if(view==='admin-reporting'){
      const data=await apiPost('patients',{user:session.user});
      if(Array.isArray(data.patients)) reports=data.patients.map(normPatient).filter(Boolean);
      renderReportingAnalytics();return;
    }
    if(view==='admin-users'){
      await refreshUsersLive();renderAdminUsers();return;
    }
    if(view==='admin-personnel'){
      const data=await apiPost('personnel',{user:session.user});
      if(Array.isArray(data.personnel)) users=data.personnel.map(normUser);
      populatePersonnelFilters();renderPersonnelDirectory('admin');return;
    }
    if(view==='admin-monitoring'){
      await refreshUnits();
      await refreshBhwRegistrationSummary(false);
      return;
    }
    if(view==='admin-patients'){
      const [data,refData]=await Promise.all([apiPost('patients',{user:session.user}),apiPost('hospitalReferrals',{user:session.user})]);
      if(Array.isArray(data.patients)) reports=data.patients.map(normPatient).filter(Boolean);
      if(Array.isArray(refData.referrals))hospitalReferrals=refData.referrals;
      populatePatientFilters();renderAdminPatients();return;
    }
    if(view==='admin-announcements'){
      const data=await apiPost('announcements',{user:session.user,activeOnly:false});
      updateAnnouncementFeedMeta(data);
      if(Array.isArray(data.announcements)){
        const pendingAnnouncements=allAnnouncements().filter(a=>a.pending||a.syncStatus==="queued");
        announcements=mergeAnnouncementLists(data.announcements.map(normAnnouncement),pendingAnnouncements);
        saveAnnouncements();
      }
      renderAdminAnnouncements();renderAdminDashboardMiniAnnouncements();renderPublicAnnouncements();return;
    }
    if(view==='admin-health-facilities'){
      await refreshHealthFacilityReports(false);
      try{
        const heat=await apiPost('heatIndex',{user:session.user});
        if(Array.isArray(heat.heatIndex)) heatIndexData=heat.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
        heatReference=heat.referenceStation||heatReference;
        renderAdminHeat();
        renderBhwHeat();
      }catch(heatErr){console.warn('Moved heat summary refresh failed',heatErr.message)}
      return;
    }
    if(view==='admin-inventory'){
      const data=await apiPost('inventory',{user:session.user,barangay:'ALL'});
      if(Array.isArray(data.inventory)) inventory=data.inventory.map(normInventory);
      persistInventoryLive();populateInventoryFilters();renderAdminInventory();return;
    }
    if(view==='admin-heat'){
      const data=await apiPost('heatIndex',{user:session.user});
      if(Array.isArray(data.heatIndex)) heatIndexData=data.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
      heatReference=data.referenceStation||heatReference;renderHeatMap('adminHeatMap2',heatIndexData);renderHeatTable('adminHeatBody2',heatIndexData,true);return;
    }
    if(view==='bhw'){
      const [data,feed]=await Promise.all([
        apiPost('dashboard',{user:session.user,deviceId:DEVICE_ID}),
        apiPost('announcements',{user:session.user,activeOnly:false})
      ]);
      updateAnnouncementFeedMeta(feed);
      if(Array.isArray(data.patients)) reports=data.patients.map(normPatient).filter(Boolean);
      if(Array.isArray(data.inventory)) inventory=data.inventory.map(normInventory);
      const authoritativeAnnouncements=Array.isArray(feed.announcements)
        ? feed.announcements.map(normAnnouncement)
        : (Array.isArray(data.announcements) ? data.announcements.map(normAnnouncement) : null);
      if(authoritativeAnnouncements){
        const pendingAnnouncements=allAnnouncements().filter(a=>a.pending||a.syncStatus==="queued");
        announcements=mergeAnnouncementLists(authoritativeAnnouncements,pendingAnnouncements);
        saveAnnouncements();
      }
      if(Array.isArray(data.heatIndex)) heatIndexData=data.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
      renderBhw();renderBhwAnnouncements();renderBhwDashboardMiniAnnouncements();renderBhwInventory();renderBhwHeat();maybeShowBhwAnnouncementPopup();return;
    }
    if(view==='bhw-patients'){
      const data=await apiPost('patients',{user:session.user});
      if(Array.isArray(data.patients)) reports=data.patients.map(normPatient).filter(Boolean);
      renderBhwPatientRecords();return;
    }
    if(view==='bhw-heat'){
      const data=await apiPost('heatIndex',{user:session.user,barangay:session.barangay});
      if(Array.isArray(data.heatIndex)) heatIndexData=data.heatIndex.map(normHeat).filter(x=>BARANGAYS.includes(x.barangay)&&Number.isFinite(x.value));
      heatReference=data.referenceStation||heatReference;renderBhwHeatDetailed();return;
    }
    if(view==='bhw-personnel'){
      const data=await apiPost('personnel',{user:session.user});
      if(Array.isArray(data.personnel)) users=data.personnel.map(normUser);
      populatePersonnelFilters();renderPersonnelDirectory('bhw');return;
    }
    if(view==='bhw-announcements'){
      const [a,p]=await Promise.all([
        apiPost('announcements',{user:session.user,activeOnly:false}),
        apiPost('publicAnnouncements',{})
      ]);
      updateAnnouncementFeedMeta(a);
      updateAnnouncementFeedMeta(p);
      if(Array.isArray(a.announcements)){
        const pendingAnnouncements=allAnnouncements().filter(x=>x.pending||x.syncStatus==="queued");
        announcements=mergeAnnouncementLists(a.announcements.map(normAnnouncement),pendingAnnouncements);
      }
      if(Array.isArray(p.announcements)){
        // The public feed is also a canonical confirmation source; keep it merged
        // with the BHW-scoped feed and the local pending queue.
        const pendingAnnouncements=allAnnouncements().filter(x=>x.pending||x.syncStatus==="queued");
        announcements=mergeAnnouncementLists(mergeAnnouncementLists(announcements,p.announcements.map(normAnnouncement)),pendingAnnouncements);
      }
      saveAnnouncements();
      renderBhwAnnouncements();renderPublicAnnouncements();maybeShowBhwAnnouncementPopup();return;
    }
    if(view==='bhw-inventory'){
      await refreshBhwInventoryLive();return;
    }
    if(view==='hospital-dashboard'){
      await refreshHospitalDashboard(false);return;
    }
  }catch(err){
    console.warn('Module refresh failed',view,err.message);
    if(view==='public'){publicAnnouncementsLoading=false;publicAnnouncementsLoadError=true;renderPublicAnnouncements();}
  }
}

function placeNetworkBanner(){
 const banner=document.getElementById("networkBanner");
 const slot=document.getElementById("publicNetworkSlot");
 const content=document.querySelector(".content");
 if(!banner||!content)return;
 const isPublic=document.body.classList.contains("public-mode") && !!slot;
 if(isPublic){
   if(banner.parentElement!==slot)slot.appendChild(banner);
 }else{
   if(banner.parentElement!==content)content.insertBefore(banner,content.firstElementChild);
 }
}

function mergeAnnouncementLists(a,b){
  const map=new Map();[...(a||[]),...(b||[])].forEach(x=>{if(x?.id)map.set(String(x.id),x)});return [...map.values()]
}
