async function submitModalReport(e){
 e.preventDefault();
 if(!session||session.role!=='admin'){alert('Admin login is required to create a patient report.');return;}
 const f=e.currentTarget||e.target,q=s=>f.querySelector(s),selected=f.querySelector('input[name="modalCondition"]:checked');
 if(!selected){alert('Please select a condition.');return;}
 const files=Array.from(q('#rAttachments')?.files||[]);if(files.length>10){alert('Select no more than 10 photos per patient report.');return;}
 if(files.length&&(!LIVE_API_URL||!navigator.onLine)){alert('Selected laboratory/photos require an internet connection for secure upload. Reconnect before submitting, or remove the photos and submit without attachments.');return;}
 const ageText=q('#rAge').value.trim(),reportId=f.dataset.pendingReportId||makeReportId();
 const r={reportId:reportId,deviceId:DEVICE_ID,date:q('#rDate').value,name:q('#rName').value.trim(),age:ageText===''?'':Number(ageText),barangay:q('#rBarangay').value,condition:selected.value,sex:q('#rSex').value,contact:q('#rContact').value.trim(),bp:q('#rBp').value.trim(),temp:q('#rTemp').value,hr:q('#rHr').value,rr:q('#rRr').value,o2sat:q('#rO2Sat').value,gcs:q('#rGcs').value,chiefComplaint:q('#rChiefComplaint').value.trim(),workingDiagnosis:q('#rWorkingDiagnosis').value.trim(),disposition:q('#rDisposition').value,notes:q('#rNotes').value.trim(),status:q('#rCritical').checked?'Critical':'Review',critical:q('#rCritical').checked,createdAt:new Date().toISOString()};
 if(!r.name||!r.condition){alert('Patient name and condition are required.');return;}
 if(isDuplicateReport(r)&&!f.dataset.pendingReportId){alert('Duplicate report detected.');return;}
 const btn=f.querySelector('button[type="submit"]'),oldText=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='Saving report…';}
 try{
  if(LIVE_API_URL&&navigator.onLine){
   let result;
   try{result=await apiPost('savePatient',{user:session.user,patient:r,deviceId:DEVICE_ID});if(!result||result.ok!==true||!result.patient)throw new Error('Backend did not confirm the saved patient record.');}
   catch(apiErr){if(files.length||f.dataset.pendingReportId){f.dataset.pendingReportId=reportId;alert('Patient save was not confirmed. Keep this form open and retry when connected; the same report ID will be reused.\n\n'+apiErr.message);return;}r.syncStatus='queued';r.syncError=apiErr.message;reports.push(r);queueForSync(r);persistReports();persistOutbox();renderAll();closeReportModal();alert('Report queued for retry; Google Sheets save is not confirmed.\n\n'+apiErr.message);showView('admin');return;}
   const saved=normPatient(result.patient||r);reports=[...reports.filter(x=>String(x.reportId)!==String(r.reportId)),...(saved?[saved]:[])];persistReports();renderAll();f.dataset.pendingReportId=reportId;
   let uploaded=[];try{uploaded=await uploadSelectedPatientAttachments(f,reportId,btn);}catch(uploadErr){alert('Patient report saved, but one or more photos were not confirmed. Keep this window open and submit again to retry the same report ID.\n\n'+uploadErr.message);return;}
   delete f.dataset.pendingReportId;delete f.dataset.attachmentEventIds;f.reset();updatePatientAttachmentList(q('#rAttachments'));closeReportModal();await refreshAdminHospitalData(false);alert('Patient record saved and verified in Google Sheets.'+(uploaded.length?' '+uploaded.length+' private photo attachment(s) uploaded.':''));showView('admin');return;
  }
  if(files.length){alert('Photos can only be uploaded online. Reconnect or remove the selected photos before submitting.');return;}
  reports.push(r);queueForSync(r);persistReports();persistOutbox();renderAll();closeReportModal();alert('Offline: report queued locally and is not yet confirmed in Google Sheets.');showView('admin');
 }finally{if(btn){btn.disabled=false;btn.textContent=oldText||'Save Patient Report';}}
}


function exportCSV(){
 const rows=[["Date","Patient","Age","Barangay","Condition","Disposition","Status","Critical"]];
 reports.forEach(r=>rows.push([r.date,r.name,r.age,r.barangay,r.condition,r.disposition,r.status,r.critical?"Yes":"No"]));
 const csv=rows.map(row=>row.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n");
 const blob=new Blob([csv],{type:"text/csv"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="super_el_nino_heat_reports.csv";a.click();URL.revokeObjectURL(url)
}
function fmtDate(s){return new Date(s).toLocaleString([], {month:"short",day:"numeric",year:"numeric",hour:"2-digit",minute:"2-digit"})}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}

